/* ---- record §52-A: the pose callbacks 0x3F7F4/0x3F85C/0x3FD30/0x3FEF8, the
 * reaction callback 0x3FFDC, the confetti pool 0x40608/0x407EC/0x40554, and
 * character 1's 0x21 cluster 0x21C84/0x21D10/0x21A88/0x21B08/0x21B74/0x21BE8
 * with 0x215B0. Every part runs between g2_save and g2_restore. ------------ */

#define P52_1080B0 0x001080B0u   /* the pool countdown word (no symbols.h name) */
#define P52_1080B2 0x001080B2u   /* 0x40554's step word */
#define P52_108098 0x00108098u   /* 0x40554's actor */
#define P52_NODE(i) (0x00107F00u + (u32)(i) * 0xCu)
#define P52_AUX     (FIGHT_RECS + 0x400u)   /* a palette entry with a zero count */

/* A whole-state reference: the data object, the fixture region and the
 * record pool, for the differential checks. */
static u8 p52_ref_data[0x10B0D0u - 0x80000u], p52_ref_fix[0x18000u], p52_ref_rp[0xEBA0u];

static void p52_ref_take(void)
{
    tf_snap(p52_ref_data, 0x80000u, sizeof p52_ref_data);
    tf_snap(p52_ref_fix, FIGHT_ACTORS, sizeof p52_ref_fix);
    tf_snap(p52_ref_rp, DSD(DS_001014F4), sizeof p52_ref_rp);
}

static int p52_same(void)
{
    return memcmp(p52_ref_data, mem + 0x80000u, sizeof p52_ref_data) == 0
        && memcmp(p52_ref_fix, mem + FIGHT_ACTORS, sizeof p52_ref_fix) == 0
        && memcmp(p52_ref_rp, mem + DSD(DS_001014F4), sizeof p52_ref_rp) == 0;
}

/* fs_seed plus the heads and tables the §52-A callbacks start, from the
 * state g2_save took (every caller runs between g2_save and g2_restore), so
 * no row inherits another's writes. */
static void p52_seed(u32 c0, u32 c1, int hook)
{
    g2_restore();
    fs_seed(c0, c1, hook);
    fs_tab(0x000A824Cu, 6u, 0x1570u);      /* 0x21994's other-side stream */
    fs_tab(0x000C8950u, 7u, 0x1560u);      /* 0x21D10's stream */
    fs_head(0x000E7DC4u, 0x15F0u);         /* 0x3F85C's ctx[4] stream */
    fs_head(0x000E7E9Eu, 0x15F1u);         /* 0x3F85C's 0x108080 actor stream */
    fs_head(0x000E49C4u, 0x15F2u);         /* 0x21994's own stream */
    fs_head(0x000E8F0Au, 0x15F3u);         /* 0x407EC's landed stream */
}

/* The geometry 0x18C14's flag 5 tests (0x1DDF4 on the other side's character
 * byte of the box tables ta (|dx| <= byte << 6) and tb (|dy| <= byte << 6)).
 * The records sit 0x1000 apart in x and 0x100 in y; the distances are read
 * back from the latched slots (the other slot's +0x42 bit 3, which the caller
 * sets first, picks the latch path). Mode 0 passes with the smallest bytes
 * that do, so that swapping the tables fails; mode 1 fails x, mode 2 fails y. */
static void p52_geo(u32 sd, u32 ta, u32 tb, int mode)
{
    u32 och = (u32)DSB(DS_001077B0 + (1u - sd) * 0x94u + 0x7Au);
    s32 d1, d2;
    u32 va, vb;
    DSD(FIGHT_RECS + 0x18u) = 0x1000u;
    DSD(FIGHT_RECS + 0x118u) = 0x2000u;
    DSD(FIGHT_RECS + 0x1Cu) = 0x500u;
    DSD(FIGHT_RECS + 0x11Cu) = 0x600u;
    fighter_slot_latch(0u);
    fighter_slot_latch(1u);
    d1 = (s32)DSD(DS_001077B0 + 0x2Cu) - (s32)DSD(DS_001077B0 + 0x94u + 0x2Cu);
    d2 = (s32)DSD(DS_001077B0 + 0x30u) - (s32)DSD(DS_001077B0 + 0x94u + 0x30u);
    if (d1 < 0) d1 = -d1;
    if (d2 < 0) d2 = -d2;
    CHECK(d2 >= 0x80 && d1 > d2 + 0x80 && d1 < 0x3F00,
          "p52_geo: the fixture separates the x and y tables");
    va = (u32)d1 / 64u + 1u;
    vb = (u32)d2 / 64u + 1u;
    if (mode == 1) va = (u32)d1 / 64u - 1u;
    if (mode == 2) vb = (u32)d2 / 64u - 1u;
    DSB(ta + och) = (u8)va;
    DSB(tb + och) = (u8)vb;
}

/* sc_m2 for side 0's hooks on the p52 fixture: 0x3B298(1, slot 0's +0x5F = 0)
 * returns 1 and sets slot 1's +0x43 bit 5 (slot 0's character's 0xA6728 word
 * +2 = 0 lets the scan run; side 1's command word carries both facing bits). */
static void p52_m2(void)
{
    sc_m2();
    DSW(0x000A6728u + (u32)DSB(DS_001077B0 + 0x7Au) * 0x180u + 2u) = 0;
    DSW(DS_001088E2) = 0x3000u;
}

static void check_p52_registered(void)
{
    static const struct { u32 a; void (*f)(void); } t[] = {
        { 0x3F7F4u, (void (*)(void))fighter_3f7f4 }, { 0x3F85Cu, (void (*)(void))fighter_3f85c },
        { 0x3FD30u, (void (*)(void))fighter_3fd30 }, { 0x3FEF8u, (void (*)(void))fighter_3fef8 },
        { 0x3FFDCu, (void (*)(void))fighter_3ffdc }, { 0x21C84u, (void (*)(void))fighter_21c84 },
        { 0x21D10u, (void (*)(void))fighter_21d10 }, { 0x21A88u, (void (*)(void))fighter_21a88 },
        { 0x21B08u, (void (*)(void))fighter_21b08 }, { 0x21B74u, (void (*)(void))fighter_21b74 },
        { 0x21BE8u, (void (*)(void))fighter_21be8 }, { 0x40554u, fighter_40554 },
        { 0x407ECu, fighter_407ec },
    };
    u32 i;
    for (i = 0; i < sizeof t / sizeof t[0]; i++)
        CHECK(fn_resolve(t[i].a) == t[i].f, "a record §52-A callback is registered");
    /* The raw dwords that reach them (the LE image, fixups applied). */
    CHECK_EQ_INT((int)DSD(0x000A50E4u), 0x3FFDC);     /* char 5, reaction 0x23 */
    CHECK_EQ_INT((int)DSD(0x000A3CE4u), 0x21C84);     /* char 1, reaction 0x23 */
    CHECK_EQ_INT((int)DSD(0x000A3CF8u), 0x21D10);     /* char 1, reaction 0x24 */
    CHECK_EQ_INT((int)DSD(DS_000A8644 + 13u * 4u), 0x40554);
    CHECK_EQ_INT((int)DSD(DS_000A8644 + 14u * 4u), 0x407EC);
}

/* 0x3F7F4 (side): the +0x57 == 1 gate, then 0x18C14 with flag 5 = 1 and
 * flags 1, 4, 8, 0xE = 0 on 0xC7720/0xC772A. Each row is compared with
 * 0x18C14 from the same state; the rows' outcomes are pinned too. */
static void check_p52_3f7f4(void)
{
    static const struct { u8 v57; int mode; int k; int want; } row[] = {
        { 1u, 0, 0, 0 },   /* passes; with the tables swapped it would fail */
        { 0u, 0, 0, 1 }, { 2u, 0, 0, 1 }, { 0xFFu, 0, 0, 1 },
        { 1u, 1, 0, 1 }, { 1u, 2, 0, 1 },
        { 1u, 0, 1, 1 },   /* flag 1: the other slot's +0x74 */
        { 1u, 0, 2, 1 },   /* flag 4: the other slot's +0x54 == 2 */
        { 1u, 0, 3, 1 },   /* flag 8: the other slot's +0x42 bit 3 */
        { 1u, 0, 5, 1 },   /* flag 0xE: 0x3B298 returns 1 (side 0 only) */
    };
    u32 sd, i, j;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
        for (i = 0; i < sizeof row / sizeof row[0]; i++) {
            u8 f[16];
            u32 got;
            int want;
            if (row[i].k == 5 && sd != 0u) continue;
            p52_seed(2u, 4u, 0);
            DSB(o + 0x42u) = row[i].k == 3 ? 8u : 0u;
            p52_geo(sd, 0x000C7720u, 0x000C772Au, row[i].mode);
            DSB(s + 0x57u) = row[i].v57;
            DSB(o + 0x54u) = 0u;
            if (row[i].k == 1) DSW(o + 0x74u) = 1u;
            if (row[i].k == 2) DSB(o + 0x54u) = 2u;
            if (row[i].k == 5) p52_m2();
            for (j = 0; j < 16u; j++) f[j] = 2u;
            f[5] = 1u; f[1] = 0u; f[4] = 0u; f[8] = 0u; f[0xE] = 0u;
            sc_snap();
            want = row[i].v57 == 1u ? fighter_18c14(sd, f, 0x000C7720u, 0x000C772Au) : 1;
            sc_back();
            got = fighter_3f7f4(sd);
            CHECK_EQ_INT((int)got, want);
            CHECK_EQ_INT(want, row[i].want);
            if (i == 0u) {
                /* the fixture separates EBX from ECX */
                for (j = 0; j < 16u; j++) f[j] = 2u;
                f[5] = 1u; f[1] = 0u; f[4] = 0u; f[8] = 0u; f[0xE] = 0u;
                sc_snap();
                CHECK_EQ_INT(fighter_18c14(sd, f, 0x000C772Au, 0x000C7720u), 1);
                sc_back();
            }
        }
    }
}

/* 0x3FD30 (side): ctx[4]'s +0x61 gate; 0x18C14 with flag 5 = 1 and 1, 4,
 * 7, 8, 0xE = 0 on 0xC7742/0xC774C; r == 0 sets ctx[2]'s +0x57 = 1, r == 1
 * runs the 4/4 state with 0x36870. The reference runs the same steps from
 * the same state (whole-state compare). */
static void check_p52_3fd30(void)
{
    static const struct { u8 v61; int mode; int k; int want; } row[] = {
        { 0x61u, 0, 0, 0 }, { 0u, 0, 0, 1 },
        { 0x61u, 1, 0, 1 }, { 0x61u, 2, 0, 1 },
        { 0x61u, 0, 1, 1 }, { 0x61u, 0, 2, 1 },
        { 0x61u, 0, 4, 1 },   /* flag 7: the other slot's +0x62 */
        { 0x61u, 0, 3, 1 },   /* flag 8: the other slot's +0x42 bit 3 */
        { 0x61u, 0, 5, 1 },   /* flag 0xE: 0x3B298 returns 1 (side 0 only) */
        { 0x61u, 1, 6, 1 },   /* +0x54 = 3: 0x36870's case 3 keeps +0x52/+0x53 */
    };
    u32 sd, i, j;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u;
        for (i = 0; i < sizeof row / sizeof row[0]; i++) {
            u8 f[16];
            u32 got;
            int want;
            if (row[i].k == 5 && sd != 0u) continue;
            p52_seed(2u, 4u, 0);
            DSB(o + 0x42u) = row[i].k == 3 ? 8u : 0u;
            p52_geo(sd, 0x000C7742u, 0x000C774Cu, row[i].mode);
            DSW(DS_00104B00) = 0x15u;
            DSB(r + 0x61u) = row[i].v61;
            DSB(s + 0x57u) = 0x57u;
            DSB(s + 0x52u) = 0x52u; DSB(s + 0x53u) = 0x53u; DSB(s + 0x8Au) = 0x8Au;
            DSB(o + 0x54u) = 0u;
            if (row[i].k == 1) DSW(o + 0x74u) = 1u;
            if (row[i].k == 2) DSB(o + 0x54u) = 2u;
            if (row[i].k == 4) DSB(o + 0x62u) = 1u;
            if (row[i].k == 5) p52_m2();
            if (row[i].k == 6) DSB(s + 0x54u) = 3u;
            sc_snap();
            if (row[i].v61 == 0u) {
                want = 1;
            } else {
                for (j = 0; j < 16u; j++) f[j] = 2u;
                f[5] = 1u; f[1] = 0u; f[4] = 0u; f[7] = 0u; f[8] = 0u; f[0xE] = 0u;
                want = fighter_18c14(sd, f, 0x000C7742u, 0x000C774Cu);
                if (want == 1) {
                    DSB(s + 0x8Au) = 0u; DSB(s + 0x52u) = 4u; DSB(s + 0x53u) = 4u;
                    DSB(r + 0x61u) = 0u;
                    fighter_36870(r);
                }
                if (want == 0) DSB(s + 0x57u) = 1u;
            }
            p52_ref_take();
            sc_back();
            got = fighter_3fd30(sd);
            CHECK_EQ_INT((int)got, want);
            CHECK_EQ_INT(want, row[i].want);
            CHECK(p52_same(), "0x3FD30: the state is the reference's");
            if (row[i].v61 == 0u) {
                CHECK_EQ_INT((int)DSB(s + 0x57u), 0x57);
                CHECK_EQ_INT((int)DSB(s + 0x52u), 0x52);
            } else if (want == 0) {
                CHECK_EQ_INT((int)DSB(s + 0x57u), 1);
                CHECK_EQ_INT((int)DSB(s + 0x52u), 0x52);
                CHECK_EQ_INT((int)DSB(r + 0x61u), 0x61);
            } else {
                CHECK_EQ_INT((int)DSB(r + 0x61u), 0);
                if (row[i].k == 5) CHECK_EQ_INT((int)(DSB(o + 0x43u) & 0x20u), 0x20);
                if (row[i].k == 6) {
                    CHECK_EQ_INT((int)DSB(s + 0x52u), 4);
                    CHECK_EQ_INT((int)DSB(s + 0x53u), 4);
                }
            }
        }
    }
}

/* 0x3F85C (side), both sides, both flips, with and without the side's
 * 0x108080 actor, two landing words. Direct post-conditions (both slots'
 * +0x42 bit 3 set, so every latch copies the record) and a whole-state
 * reference of the same callee sequence. */
static void check_p52_3f85c(void)
{
    u32 k;
    for (k = 0; k < 16u; k++) {
        u32 sd = k & 1u, fl = (k >> 1) & 1u, withact = (k >> 2) & 1u, neg = k >> 3;
        u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u, ro = FIGHT_RECS + (1u - sd) * 0x100u;
        u32 a = FIGHT_RECS + 0x200u, a2 = FIGHT_RECS + 0x300u;
        u32 cs = sd ? 3u : 1u, och = sd ? 2u : 5u;
        u16 land = neg ? 0xFF00u : 0x1234u;
        s32 y = (s32)(s16)land - 0x3C0;
        s32 xo = 0x5000;
        p52_seed(cs, och, 0);
        DSB(s + 0x7Au) = (u8)cs;
        DSB(o + 0x7Au) = (u8)och;
        fs_flip(sd, (int)fl);
        DSB(DS_001078FA) = 2u;
        mem_fill(a, 0, 0x200u);
        DSW(a + 0x56u) = 3u; DSD(a + 0x08u) = 0x0A0A0A0Au;
        DSW(a2 + 0x56u) = 4u; DSD(a2 + 0x08u) = 0x0B0B0B0Bu;
        DSD(DS_00108080 + sd * 4u) = withact ? a : 0u;
        DSD(DS_00108080 + (1u - sd) * 4u) = a2;
        DSW(0x000BD884u + cs * 2u) = land;
        DSD(r + 0x18u) = 0x1800u; DSD(r + 0x1Cu) = 0x700u;
        DSD(ro + 0x18u) = (u32)xo; DSD(ro + 0x1Cu) = 0x900u;
        DSW(r + 0x34u) = 0x3434u; DSW(ro + 0x34u) = 0x3434u;
        DSW(r + 0x36u) = 0x3636u; DSW(ro + 0x36u) = 0x3636u;
        DSW(r + 0x44u) = 0x4444u; DSW(ro + 0x44u) = 0x4444u;
        DSB(r + 0x42u) = 0x42u; DSB(ro + 0x42u) = 0x42u;
        DSB(r + 0x43u) = 0x43u; DSB(ro + 0x43u) = 0x43u;
        DSB(r + 0x59u) = 0x59u; DSB(ro + 0x59u) = 0x5Au;
        DSB(s + 0x52u) = 0x52u; DSB(s + 0x53u) = 0x53u; DSB(s + 0x54u) = 0x54u;
        DSB(s + 0x57u) = 0x99u; DSD(s + 0x10u) = 0x10101010u; DSB(s + 0x41u) = 0x01u;
        DSB(o + 0x52u) = 0x52u; DSB(o + 0x53u) = 0x53u; DSB(o + 0x54u) = 0x54u;
        DSB(o + 0x57u) = 0x98u; DSD(o + 0x10u) = 0x10101010u; DSB(o + 0x41u) = 0x01u;
        DSW(s + 0x74u) = 0x7474u; DSW(o + 0x74u) = 0x7575u;

        /* the reference: the same callees in the raw's order */
        sc_snap();
        fighter_3c148(0u); fighter_3c148(1u); fighter_3c16c(0u); fighter_3c16c(1u);
        hit_flash_pair(sd);
        hit_anchor_set(1u - sd, DSD(ro + 0x18u), 0u);
        actors_anim_begin(ro, DSD(0x000C9170u + och * 4u), 0x40400000u);
        DSB(s + 0x54u) = 0u; DSB(s + 0x57u) = 2u;
        hit_anchor_y(sd, (u32)y);
        hit_anchor_x(sd, fighter_actor_bit15_clear(sd) ? DSD(o + 0x2Cu) + 0x280u
                                                       : DSD(o + 0x2Cu) - 0x280u);
        fighter_39a10(r, 0x309u); fighter_39a10(ro, 0x309u);
        actors_anim_begin(r, 0x000E7DC4u, 0x40400000u);
        if (withact) actors_anim_begin(a, 0x000E7E9Eu, 0u);
        DSB(o + 0x52u) = 0x10u; DSB(o + 0x53u) = 0x0Au; DSB(o + 0x54u) = 0u;
        DSD(o + 0x10u) = 0u; DSB(o + 0x41u) = (u8)(DSB(o + 0x41u) | 0x80u);
        p52_ref_take();
        sc_back();

        fighter_3f85c(sd);
        CHECK(p52_same(), "0x3F85C: the state is the reference's");
        CHECK_EQ_INT((int)DSW(r + 0x34u), 0); CHECK_EQ_INT((int)DSW(ro + 0x34u), 0);
        CHECK_EQ_INT((int)DSW(r + 0x36u), 0); CHECK_EQ_INT((int)DSW(ro + 0x36u), 0);
        CHECK_EQ_INT((int)DSW(r + 0x44u), 0); CHECK_EQ_INT((int)DSW(ro + 0x44u), 0);
        CHECK_EQ_INT((int)DSB(r + 0x42u), 0); CHECK_EQ_INT((int)DSB(ro + 0x43u), 0);
        CHECK_EQ_INT((int)DSB(r + 0x59u), 1); CHECK_EQ_INT((int)DSB(ro + 0x59u), 0xFF);
        CHECK_EQ_INT((int)DSD(ro + 0x18u), xo);
        CHECK_EQ_INT((int)DSD(ro + 0x1Cu), 0);
        CHECK_EQ_INT((int)DSD(o + 0x2Cu), xo);
        sc_stream(ro, fs_stream(2u, och), 0x40400000u, (u16)(0x15A0u + och));
        CHECK_EQ_INT((int)DSB(s + 0x54u), 0);
        CHECK_EQ_INT((int)DSB(s + 0x57u), 2);
        CHECK_EQ_INT((int)DSB(s + 0x52u), 0x52);
        CHECK_EQ_INT((int)DSD(r + 0x1Cu), y);
        CHECK_EQ_INT((int)DSD(s + 0x30u), y);
        CHECK_EQ_INT((int)DSD(s + 0x2Cu), xo + (fl ? -0x280 : 0x280));
        CHECK_EQ_INT((int)DSD(r + 0x18u), 0x1800);
        CHECK_EQ_INT((int)DSW(s + 0x74u), 0x0309);
        CHECK_EQ_INT((int)DSW(o + 0x74u), 0x0309);
        sc_stream(r, 0x000E7DC4u, 0x40400000u, 0x15F0u);
        if (withact) sc_stream(a, 0x000E7E9Eu, 0u, 0x15F1u);
        else CHECK_EQ_INT((int)DSD(a + 0x08u), 0x0A0A0A0A);
        CHECK_EQ_INT((int)DSD(a2 + 0x08u), 0x0B0B0B0B);
        CHECK_EQ_INT((int)DSB(o + 0x52u), 0x10);
        CHECK_EQ_INT((int)DSB(o + 0x53u), 0x0A);
        CHECK_EQ_INT((int)DSB(o + 0x54u), 0);
        CHECK_EQ_INT((int)DSD(o + 0x10u), 0);
        CHECK_EQ_INT((int)DSB(o + 0x41u), 0x81);
        CHECK_EQ_INT((int)DSB(s + 0x41u), 0x01);
        CHECK_EQ_INT((int)DSD(s + 0x10u), 0x10101010);
    }
}

/* 0x3FEF8 (slot, rec, side): builds a context and changes nothing. */
static void check_p52_3fef8(void)
{
    u32 sd;
    for (sd = 0; sd < 2u; sd++) {
        p52_seed(1u, 3u, 0);
        DSB(DS_001077B0 + sd * 0x94u + 0x57u) = 0x57u;
        p52_ref_take();
        fighter_3fef8(DS_001077B0 + sd * 0x94u, FIGHT_RECS + sd * 0x100u, sd);
        CHECK(p52_same(), "0x3FEF8 leaves the state alone");
    }
}

/* 0x3FFDC (slot, rec, side): the slot's +0x4E = |0x187FC()| / 30 (signed
 * truncation), negated when the record's side is unflipped; then 0x3FF08. */
static void check_p52_3ffdc(void)
{
    static const s32 dx[] = { 1000, -1000, 29, -61, 0, 30, -0x7000 };
    u32 sd, fl, i;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u, r = FIGHT_RECS + sd * 0x100u;
        for (fl = 0; fl < 2u; fl++) {
            for (i = 0; i < sizeof dx / sizeof dx[0]; i++) {
                s32 m = dx[i] < 0 ? -dx[i] : dx[i];
                s32 v = m / 30;
                p52_seed(5u, 5u, 0);
                fs_flip(sd, (int)fl);
                DSD(FIGHT_RECS + 0x18u) = (u32)(0x10000 + dx[i]);
                DSD(FIGHT_RECS + 0x118u) = 0x10000u;
                DSW(s + 0x4Eu) = 0x4E4Eu;
                DSB(r + 0x53u) = 0x77u;
                DSD(s + 0x0Cu) = 0x0C0C0C0Cu; DSD(s + 0x18u) = 0x18181818u; DSD(s + 0x1Cu) = 0x1C1C1C1Cu;
                fighter_3ffdc(s, r, 9u);
                CHECK_EQ_INT((int)DSW(s + 0x4Eu), (int)(u16)(fl ? v : -v));
                CHECK_EQ_INT((int)DSB(r + 0x53u), 1);
                CHECK_EQ_INT((int)DSD(s + 0x0Cu), 0x3FEF8);
                CHECK_EQ_INT((int)DSD(s + 0x18u), 0x3FD30);
                CHECK_EQ_INT((int)DSD(s + 0x1Cu), 0x3FDD8);
                sc_stream(r, 0x000D4C66u, 0x40400000u, 0x15EAu);
            }
        }
        /* 0x3FF08's null gate: the +0x4E store comes first */
        p52_seed(5u, 5u, 0);
        fs_flip(sd, 1);
        DSD(DS_001077A8 + (1u - sd) * 4u) = 0u;
        DSD(FIGHT_RECS + 0x18u) = 0x10000u + 300u;
        DSD(FIGHT_RECS + 0x118u) = 0x10000u;
        DSW(s + 0x4Eu) = 0x4E4Eu;
        DSD(s + 0x0Cu) = 0x0C0C0C0Cu;
        fighter_3ffdc(s, r, 0u);
        CHECK_EQ_INT((int)DSW(s + 0x4Eu), 10);
        CHECK_EQ_INT((int)DSD(s + 0x0Cu), 0x0C0C0C0C);
    }
}

/* The confetti pool fixture: the other player's slot and record as
 * check_fs_406b4 seeds them. */
static void p52_pool_seed(u32 d4)
{
    u32 e = d4 ^ 1u;
    u32 se = DS_001077B0 + e * 0x94u, re = FIGHT_RECS + e * 0x100u;
    p52_seed(1u, 3u, 0);
    DSD(DS_00104AD4) = d4;
    DSD(se + 0x2Cu) = 0x2C2Cu;
    DSD(se + 0x30u) = 0x3030u;
    DSD(re + 0x30u) = 0x07770000u;
}

/* Walk a {next, prev} list from its sentinel; returns the count, 0xFFFF on a
 * broken prev link or more than 40 nodes. */
static u32 p52_list(u32 head, u32 *out)
{
    u32 n = 0, p = head, q = DSD(head);
    while (q != head) {
        if (DSD(q + 4u) != p || n >= 40u) return 0xFFFFu;
        if (out) out[n] = q;
        n++;
        p = q;
        q = DSD(q);
    }
    if (DSD(head + 4u) != p) return 0xFFFFu;
    return n;
}

/* 0x40608: the sentinels, the 32 nodes on the free list in address order,
 * the countdown 8 and one 0x406B4 burst of eight. */
static void check_p52_40608(void)
{
    u32 d4;
    for (d4 = 0; d4 < 2u; d4++) {
        u32 live[40], freel[40], i, n0, nl, nf;
        p52_pool_seed(d4);
        DSD(DS_00107EF0) = 0x11111111u; DSD(DS_00107EF0 + 4u) = 0x22222222u;
        DSD(DS_00107EF8) = 0x33333333u; DSD(DS_00107EF8 + 4u) = 0x44444444u;
        for (i = 0; i < 32u; i++) {
            DSD(P52_NODE(i)) = 0x5A5A5A5Au;
            DSD(P52_NODE(i) + 4u) = 0xA5A5A5A5u;
            DSD(P52_NODE(i) + 8u) = 0xDEAD0000u + i;
        }
        DSD(DS_00108080) = 0x80808080u;
        DSD(DS_00108080 + 4u) = 0x84848484u;
        DSW(P52_1080B0) = 0x1234u;
        DSB(DS_00104AE9) = 0x01u;
        rng_seed(0x2468u);
        n0 = tb_active();
        fighter_40608();
        CHECK_EQ_INT((int)tb_active(), (int)(n0 + 8u));
        CHECK_EQ_INT((int)DSW(P52_1080B0), 8);
        CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x41);
        CHECK_EQ_INT((int)DSD(DS_00108080), (int)0x80808080u);
        CHECK_EQ_INT((int)DSD(DS_00108080 + 4u), (int)0x84848484u);
        nl = p52_list(DS_00107EF0, live);
        nf = p52_list(DS_00107EF8, freel);
        CHECK_EQ_INT((int)nl, 8);
        CHECK_EQ_INT((int)nf, 24);
        for (i = 0; i < 8u && nl == 8u; i++) {
            u32 node = live[i];
            CHECK_EQ_INT((int)node, (int)P52_NODE(7u - i));
            CHECK_EQ_INT((int)DSD(DSD(node + 8u) + 0x14u), (int)node);
        }
        for (i = 0; i < 24u && nf == 24u; i++) {
            CHECK_EQ_INT((int)freel[i], (int)P52_NODE(8u + i));
            CHECK_EQ_INT((int)DSD(freel[i] + 8u), (int)(0xDEAD0000u + 8u + i));
        }
    }
}

/* 0x407EC: the countdown and its burst (4 or 0 after the decrement). */
static void check_p52_407ec_count(void)
{
    static const struct { u16 t; int burst; } row[] = {
        { 0u, 0 }, { 1u, 1 }, { 2u, 0 }, { 5u, 1 }, { 6u, 0 }, { 0x8005u, 0 }, { 0x0105u, 0 },
    };
    u32 k, i;
    for (k = 0; k < sizeof row / sizeof row[0]; k++) {
        u32 n0;
        p52_pool_seed(0u);
        DSD(DS_00107EF0) = DS_00107EF0; DSD(DS_00107EF0 + 4u) = DS_00107EF0;
        DSD(DS_00107EF8) = DS_00107EF8; DSD(DS_00107EF8 + 4u) = DS_00107EF8;
        for (i = 0; i < 3u; i++) effects_list_insert_before(DS_00107EF8, P52_NODE(i));
        DSW(P52_1080B0) = row[k].t;
        DSB(DS_00104AE9) = 0x41u;
        DSB(DS_001078FC) = 0x77u;
        n0 = tb_active();
        fighter_407ec();
        CHECK_EQ_INT((int)DSW(P52_1080B0), row[k].t ? (int)(u16)(row[k].t - 1u) : 0);
        CHECK_EQ_INT((int)tb_active(), (int)(n0 + (row[k].burst ? 3u : 0u)));
        CHECK_EQ_INT((int)p52_list(DS_00107EF0, NULL), row[k].burst ? 3 : 0);
        /* an empty live list is the only way to the DS_001078FC / bit-6 exit */
        CHECK_EQ_INT((int)DSB(DS_001078FC), row[k].burst ? 0x77 : 1);
        CHECK_EQ_INT((int)DSB(DS_00104AE9), row[k].burst ? 0x41 : 0x01);
    }
}

/* 0x407EC: the walk. Eight live actors from 0x40608; the even ones landed
 * (+0x1C = 0), the odd ones take +0x2C = 0x400000 / (+0x30 >> 16). */
static void check_p52_407ec_walk(void)
{
    static const u32 z30[4] = { 0x00070000u, 0xFFFD0000u, 0x7FFF1234u, 0x0000FFFFu };
    u32 live[40], freel[40], a[8], i, nl, nf;
    u16 w2c[8];
    p52_pool_seed(0u);
    fighter_40608();
    CHECK_EQ_INT((int)p52_list(DS_00107EF0, live), 8);
    for (i = 0; i < 8u; i++) {
        a[i] = DSD(P52_NODE(i) + 8u);
        DSW(a[i] + 0x2Cu) = (u16)(0x2C00u + i);
        DSB(a[i] + 0x59u) = 0x59u;
        DSW(a[i] + 0x34u) = 0x3434u;
        DSW(a[i] + 0x38u) = 0x3838u;
        if ((i & 1u) == 0u) {
            DSD(a[i] + 0x1Cu) = 0u;
            w2c[i] = (u16)(0x2C00u + i);
        } else {
            s32 dv;
            DSD(a[i] + 0x1Cu) = 0x100u + i;
            DSD(a[i] + 0x30u) = z30[i >> 1];
            dv = (s32)z30[i >> 1] >> 16;
            w2c[i] = dv != 0 ? (u16)(0x400000 / dv) : (u16)(0x2C00u + i);
        }
    }
    DSW(P52_1080B0) = 3u;
    DSB(DS_00104AE9) = 0x41u;
    DSB(DS_001078FC) = 0x77u;
    fighter_407ec();
    CHECK_EQ_INT((int)DSW(P52_1080B0), 2);
    for (i = 0; i < 8u; i++) {
        if ((i & 1u) == 0u) {
            CHECK_EQ_INT((int)DSB(a[i] + 0x59u), 0xFC);
            sc_stream(a[i], 0x000E8F0Au, 0x40C00000u, 0x15F3u);
            CHECK_EQ_INT((int)DSW(actor_pset(a[i]) + 2u),
                         (int)(0x5Au | (DSB(a[i] + 0x5Fu) != 0u ? 0x800u : 0u)));
            CHECK_EQ_INT((int)DSW(a[i] + 0x34u), 0);
            CHECK_EQ_INT((int)DSW(a[i] + 0x38u), 0);
            CHECK_EQ_INT((int)DSB(a[i] + 0x48u), 0);
            CHECK_EQ_INT((int)DSD(a[i] + 0x14u), 0);
        } else {
            CHECK_EQ_INT((int)DSB(a[i] + 0x59u), 0x59);
            CHECK_EQ_INT((int)DSW(a[i] + 0x34u), 0x3434);
            CHECK_EQ_INT((int)DSD(a[i] + 0x14u), (int)P52_NODE(i));
            CHECK(DSB(a[i] + 0x48u) != 0u, "a flying piece keeps its type");
        }
        CHECK_EQ_INT((int)DSW(a[i] + 0x2Cu), (int)w2c[i]);
    }
    nl = p52_list(DS_00107EF0, live);
    nf = p52_list(DS_00107EF8, freel);
    CHECK_EQ_INT((int)nl, 4);
    CHECK_EQ_INT((int)nf, 28);
    for (i = 0; i < 4u && nl == 4u; i++)
        CHECK_EQ_INT((int)live[i], (int)P52_NODE(7u - 2u * i));
    for (i = 0; i < 4u && nf == 28u; i++)     /* each landed node went to the head */
        CHECK_EQ_INT((int)freel[i], (int)P52_NODE(2u * i));
    if (nf == 28u) CHECK_EQ_INT((int)freel[4], (int)P52_NODE(8u));
    CHECK_EQ_INT((int)DSB(DS_001078FC), 0x77);
    CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x41);

    /* the rest land: the list empties but the tick visited nodes, so the
     * exit waits for the next tick */
    for (i = 1u; i < 8u; i += 2u) DSD(a[i] + 0x1Cu) = 0u;
    DSW(P52_1080B0) = 0u;                   /* no countdown: no new burst */
    fighter_407ec();
    CHECK_EQ_INT((int)p52_list(DS_00107EF0, NULL), 0);
    CHECK_EQ_INT((int)DSB(DS_001078FC), 0x77);
    CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x41);
    fighter_407ec();
    CHECK_EQ_INT((int)DSB(DS_001078FC), 1);
    CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x01);
    CHECK_EQ_INT((int)DSW(P52_1080B0), 0);
}

/* 0x40554: the mover and, at 0x3800 (the word zero-extended), the pool
 * init, the actor's death, the effect, 0x37D18 and bit 5 cleared. */
static void check_p52_40554(void)
{
    static const struct { u16 w, step; int fire; } row[] = {
        { 0x1000u, 0x0100u, 0 }, { 0x37F0u, 0x000Fu, 0 }, { 0xFFF0u, 0x0020u, 0 },
        { 0x3700u, 0x0100u, 1 }, { 0x8000u, 0x1000u, 1 }, { 0x0000u, 0x3801u, 1 },
    };
    u32 k, d4;
    for (d4 = 0; d4 < 2u; d4++) {
        for (k = 0; k < sizeof row / sizeof row[0]; k++) {
            u32 e = d4 ^ 1u;
            u32 se = DS_001077B0 + e * 0x94u, re = FIGHT_RECS + e * 0x100u;
            u32 act, src;
            u16 nw = (u16)(row[k].w + row[k].step);
            p52_pool_seed(d4);
            effects_init();
            DSD(DS_001014F0) = 0u;    /* no resource entries: 0x1B544 resolves nothing */
            act = actor_spawn((const u32 *)(mem + 0x000C779Cu), 0u, 0u, 0u, 0u);
            DSD(P52_108098) = act;
            DSW(act + 0x2Cu) = row[k].w;
            DSW(P52_1080B2) = row[k].step;
            DSW(P52_1080B0) = 0x1234u;
            DSB(DS_00104AE9) = 0x21u;
            DSB(se + 0x52u) = 0x52u;
            DSW(se + 0x74u) = 0x7474u;
            src = DSD(DS_001014EC) + (u32)DSW(re + 0x56u) * 0x20u;   /* the raw's pset lookup */
            DSD(src + 0x18u) = P52_AUX;
            DSD(P52_AUX + 0x0Cu) = 0u;
            rng_seed(0x1111u);

            sc_snap();
            DSW(act + 0x2Cu) = nw;
            if (row[k].fire) {
                fighter_40608();
                actor_set_dead(act);
                (void)effects_spawn(P52_AUX, 4u, 0x0105FC30u);
                fighter_37d18(se, DSD(se));
                DSB(DS_00104AE9) = (u8)(DSB(DS_00104AE9) & 0xDFu);
            }
            p52_ref_take();
            sc_back();

            fighter_40554();
            CHECK(p52_same(), "0x40554: the state is the reference's");
            CHECK_EQ_INT((int)DSW(act + 0x2Cu), (int)nw);
            if (row[k].fire) {
                CHECK_EQ_INT((int)DSW(P52_1080B0), 8);
                CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x41);
                CHECK_EQ_INT((int)(DSB(act + 0x28u) & 8u), 8);
                CHECK_EQ_INT((int)DSB(se + 0x52u), 9);
                CHECK_EQ_INT((int)DSW(se + 0x74u), 0x0309);
                CHECK_EQ_INT((int)DSD(DSD(DS_000FCCE0) + 8u), (int)P52_AUX);
                CHECK_EQ_INT((int)DSB(DSD(DS_000FCCE0) + 0x0Du), 4);
            } else {
                CHECK_EQ_INT((int)DSW(P52_1080B0), 0x1234);
                CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x21);
                CHECK_EQ_INT((int)(DSB(act + 0x28u) & 8u), 0);
                CHECK_EQ_INT((int)DSB(se + 0x52u), 0x52);
            }
        }
    }
}

/* 0x215B0 (side): as check_fs_3e800 on the 0xA8220/0xA820C tables. */
static void check_p52_215b0(void)
{
    u32 k;
    for (k = 0; k < 4u; k++) {
        u32 sd = k & 1u, fl = k >> 1;
        u32 o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u, ro = FIGHT_RECS + (1u - sd) * 0x100u;
        u32 och = sd ? 2u : 5u;
        p52_seed(1u, 3u, 1);
        DSB(o + 0x7Au) = (u8)och;
        fs_flip(1u - sd, (int)fl);
        DSW(0x000A8222u + och * 2u) = 0xFFC0u;      /* -64 (0xA8220 + ch * 2, high word) */
        DSW(0x000A820Eu + och * 2u) = 0xFFD0u;      /* -48 (0xA820C + ch * 2, high word) */
        DSD(r + 0x18u) = 0x2000u;
        DSD(r + 0x1Cu) = 0x0300u;
        DSD(ro + 0x18u) = 0x5000u;
        DSD(ro + 0x1Cu) = 0x6000u;
        DSW(r + 0x34u) = 0x1111u;
        DSW(r + 0x36u) = 0x2222u;
        DSW(r + 0x44u) = 0x3333u;
        DSB(r + 0x4Bu) = 0x4Bu;
        DSD(ro + 0x24u) = 0x24242424u;
        DSD(ro + 0x20u) = 0x20202020u;
        DSB(ro + 0x4Bu) = 0xB4u;
        DSD(r + 0x24u) = 0x11111111u;
        fighter_215b0(sd);
        CHECK_EQ_INT((int)DSD(ro + 0x18u), 0x2000 + (fl ? -48 : 48));
        CHECK_EQ_INT((int)DSD(ro + 0x1Cu), 0x0300 - 64);
        CHECK_EQ_INT((int)DSD(r + 0x18u), 0x2000);
        CHECK_EQ_INT((int)DSD(r + 0x1Cu), 0x0300);
        CHECK_EQ_INT((int)DSW(ro + 0x34u), 0x1111);
        CHECK_EQ_INT((int)DSW(ro + 0x36u), 0x2222);
        CHECK_EQ_INT((int)DSW(ro + 0x44u), 0x3333);
        CHECK_EQ_INT((int)DSW(r + 0x34u), 0x1111);
        CHECK_EQ_INT((int)DSB(r + 0x4Bu), (int)(2u - sd));    /* the other record's +0x56 */
        CHECK_EQ_INT((int)DSB(ro + 0x4Bu), 0xB4);
        CHECK_EQ_INT((int)DSD(ro + 0x24u), 0);
        CHECK_EQ_INT((int)DSD(ro + 0x20u), 0);
        CHECK_EQ_INT((int)DSD(r + 0x24u), 0x11111111);
    }
}

/* 0x21A88 (side): as check_fs_3e924 on the 0x104764 counter and the 0xA81xx
 * box tables; 0x21B74 (side): the 1..9 window, flag 5 = 1 and 1, 4, 7, 8,
 * 0xD, 0xE = 0 on 0xA81FA/0xA8204. */
static void check_p52_21_hooks(void)
{
    static const u16 cnt[] = { 0u, 1u, 2u, 3u, 5u, 7u, 8u, 9u, 10u, 0xFFFFu, 0x8000u, 0x0103u };
    static const u16 pos[] = { 1u, 0u, 0xFFFFu, 0x7FFFu, 0x8000u };
    u32 sd, i, j, k;
    for (sd = 0; sd < 2u; sd++) {
        u32 o = DS_001077B0 + (1u - sd) * 0x94u;
        for (i = 0; i < sizeof cnt / sizeof cnt[0]; i++) {
            for (j = 0; j < sizeof pos / sizeof pos[0]; j++) {
                u8 f[16];
                u32 ch, want, got;
                int inwin = cnt[i] >= 3u && cnt[i] <= 7u;
                int useA = (s16)pos[j] > 0;
                p52_seed(1u, 3u, 0);
                DSB(o + 0x42u) = 0u;
                DSB(o + 0x54u) = 2u;
                DSD(FIGHT_RECS + 0x18u) = 0u;
                DSD(FIGHT_RECS + 0x118u) = 0x400u;
                DSD(FIGHT_RECS + 0x1Cu) = 0x500u;
                DSD(FIGHT_RECS + 0x11Cu) = 0x500u;
                ch = (u32)DSB(o + 0x7Au);
                DSB(0x000A81E6u + ch) = 0xFFu;
                DSB(0x000A81F0u + ch) = 0xFFu;
                DSB(0x000A81D2u + ch) = 0u;
                DSB(0x000A81DCu + ch) = 0u;
                DSW(DS_00104764 + sd * 2u) = cnt[i];
                DSW(DS_00104764 + (1u - sd) * 2u) = 5u;
                DSW(DS_00107D2C + sd * 2u) = pos[j];
                DSW(DS_00107D2C + (1u - sd) * 2u) = (u16)(pos[j] ? 0u : 1u);
                fs_flags(f, 1);
                want = inwin ? (u32)fighter_18c14(sd, f, useA ? 0x000A81E6u : 0x000A81D2u,
                                                  useA ? 0x000A81F0u : 0x000A81DCu) : 1u;
                got = fighter_21a88(sd);
                CHECK_EQ_INT((int)got, (int)want);
                if (inwin) CHECK_EQ_INT((int)got, useA ? 0 : 1);
            }
        }
        for (i = 0; i < 4u; i++) {
            p52_seed(1u, 3u, 0);
            DSD(FIGHT_RECS + 0x118u) = 0x400u;
            DSB(o + 0x54u) = 2u;
            DSB(0x000A81E6u + (u32)DSB(o + 0x7Au)) = 0xFFu;
            DSB(0x000A81F0u + (u32)DSB(o + 0x7Au)) = 0xFFu;
            DSW(DS_00104764 + sd * 2u) = 5u;
            DSW(DS_00107D2C + sd * 2u) = 1u;
            DSB(o + 0x42u) = 0u;
            if (i == 1u) DSW(o + 0x74u) = 1u;
            if (i == 2u) DSB(o + 0x42u) = 8u;
            if (i == 3u) DSB(o + 0x54u) = 0u;
            CHECK_EQ_INT((int)fighter_21a88(sd), i == 0u ? 0 : 1);
        }

        /* 0x21B74 */
        for (i = 0; i < sizeof cnt / sizeof cnt[0]; i++) {
            for (k = 0; k < 8u; k++) {
                u8 f[16];
                u32 want, got;
                int inwin = cnt[i] >= 1u && cnt[i] <= 9u;
                if (k == 7u && sd != 0u) continue;
                p52_seed(1u, 3u, 0);
                DSB(o + 0x42u) = 0u;
                p52_geo(sd, 0x000A81FAu, 0x000A8204u, k == 1u ? 1 : k == 5u ? 2 : 0);
                DSB(o + 0x54u) = 0u;
                if (k == 2u) DSB(o + 0x54u) = 2u;
                if (k == 3u) DSW(o + 0x74u) = 1u;
                if (k == 4u) DSB(o + 0x62u) = 1u;
                if (k == 6u) {                  /* flag 0xD: 0x39EFC(other) holds */
                    DSB(o + 0x53u) = 0x0Au;
                    DSD(o + 0x10u) = 0x00039CC8u;
                    DSB(o + 0x58u) = 4u;
                }
                if (k == 7u) p52_m2();          /* flag 0xE */
                DSW(DS_00104764 + sd * 2u) = cnt[i];
                DSW(DS_00104764 + (1u - sd) * 2u) = 5u;
                for (j = 0; j < 16u; j++) f[j] = 2u;
                f[5] = 1u; f[1] = 0u; f[4] = 0u; f[7] = 0u; f[8] = 0u; f[0xD] = 0u; f[0xE] = 0u;
                sc_snap();
                want = inwin ? (u32)fighter_18c14(sd, f, 0x000A81FAu, 0x000A8204u) : 1u;
                p52_ref_take();
                sc_back();
                got = fighter_21b74(sd);
                CHECK_EQ_INT((int)got, (int)want);
                CHECK(p52_same(), "0x21B74: the state is the reference's");
                if (inwin) CHECK_EQ_INT((int)got, k == 0u ? 0 : 1);
            }
        }
    }
}

/* 0x21B08 / 0x21BE8 (side): as check_fs_3e9a4, with 0x21994 and 0x215B0;
 * 0x21BE8 also moves the side 0xC80 down (0x1883C) and sets its record's
 * +0x36/+0x44/+0x34 after 0x21994. */
static void check_p52_21_cb(void)
{
    u32 k;
    for (k = 0; k < 8u; k++) {
        u32 sd = k & 1u, sw = (k >> 1) & 1u, be8 = k >> 2;
        u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u, ro = FIGHT_RECS + (1u - sd) * 0x100u;
        u32 och = 3u;                           /* the own side is character 1 */
        u16 v34;
        p52_seed(sd ? 3u : 1u, sd ? 1u : 3u, 1);
        fs_flip(sd, 0);
        DSB(DS_001078FA) = 2u;
        DSD(s + 0x2Cu) = sw ? 0x3000u : 0x1000u;
        DSD(o + 0x2Cu) = sw ? 0x1000u : 0x3000u;
        DSD(r + 0x18u) = 0x2000u; DSD(r + 0x1Cu) = 0x0300u;
        DSD(ro + 0x18u) = 0x5000u; DSD(ro + 0x1Cu) = 0x6000u;
        DSW(0x000A8222u + och * 2u) = 0xFFC0u;
        DSW(0x000A820Eu + och * 2u) = 0xFFD0u;
        DSB(r + 0x29u) = 0x00u;
        DSB(ro + 0x29u) = 0xFFu;
        DSB(r + 0x28u) = 0x08u;
        DSB(ro + 0x28u) = 0x08u;
        DSB(r + 0x59u) = 0x59u;
        DSB(ro + 0x59u) = 0x5Au;
        DSB(ro + 0x42u) = 0x42u;
        DSB(ro + 0x43u) = 0x43u;
        DSD(ro + 0x24u) = 0x24242424u;
        DSD(ro + 0x20u) = 0x20202020u;
        DSW(s + 0x74u) = 0x7474u;
        DSW(o + 0x74u) = 0x7575u;
        DSD(s + 0x40u) = 0x101u;
        DSB(o + 0x41u) = 0x01u;
        DSW(DS_00104764 + sd * 2u) = 0x6464u;
        DSW(DS_00104764 + (1u - sd) * 2u) = 0x6565u;
        DSW(DS_00104B00) = 0x15u;
        if (be8) fighter_21be8(sd); else fighter_21b08(sd);
        CHECK_EQ_INT((int)DSB(r + 0x59u), 1);
        CHECK_EQ_INT((int)DSB(ro + 0x59u), 0xFF);
        CHECK_EQ_INT((int)(DSB(r + 0x29u) & 0x40u), sw ? 0 : 0x40);
        CHECK_EQ_INT((int)(DSB(ro + 0x29u) & 0x40u), sw ? 0x40 : 0);
        CHECK_EQ_INT((int)DSB(ro + 0x28u), 0x28);
        CHECK_EQ_INT((int)DSB(r + 0x28u), 0x08);
        CHECK_EQ_INT((int)DSB(ro + 0x42u), 0);
        CHECK_EQ_INT((int)DSB(ro + 0x43u), 0);
        CHECK_EQ_INT((int)DSW(s + 0x74u), 0x029A);
        CHECK_EQ_INT((int)DSW(o + 0x74u), 0x029A);
        CHECK_EQ_INT((int)DSB(s + 0x52u), 9);
        CHECK_EQ_INT((int)DSB(s + 0x53u), 7);
        CHECK_EQ_INT((int)DSB(s + 0x54u), 2);
        CHECK_EQ_INT((int)DSB(s + 0x57u), 0);
        CHECK_EQ_INT((int)DSD(s + 0x0Cu), 0x216EC);
        CHECK_EQ_INT((int)DSD(s + 0x40u), 0x48101);
        CHECK_EQ_INT((int)DSB(o + 0x52u), 0x10);
        CHECK_EQ_INT((int)DSB(o + 0x53u), 0x0A);
        CHECK_EQ_INT((int)DSB(o + 0x58u), 3);
        CHECK_EQ_INT((int)DSD(o + 0x10u), 0x21458);
        CHECK_EQ_INT((int)DSB(o + 0x41u), 0x81);
        CHECK_EQ_INT((int)DSW(DS_00104764 + sd * 2u), 0);
        CHECK_EQ_INT((int)DSW(DS_00104764 + (1u - sd) * 2u), 0x6565);
        sc_stream(r, 0x000E49C4u, 0x40400000u, 0x15F2u);
        sc_stream(ro, fs_stream(6u, och), 0u, (u16)(0x1570u + och));
        v34 = (u16)(sw ? 0u - (be8 ? 0x4Bu : 0x64u) : (be8 ? 0x4Bu : 0x64u));
        CHECK_EQ_INT((int)DSW(r + 0x34u), (int)v34);
        CHECK_EQ_INT((int)DSW(r + 0x36u), be8 ? 0x01C2 : 0x00FA);
        CHECK_EQ_INT((int)DSW(r + 0x44u), be8 ? 0x0019 : 0x000F);
        CHECK_EQ_INT((int)DSW(ro + 0x34u), (int)v34);
        CHECK_EQ_INT((int)DSW(ro + 0x36u), be8 ? 0x01C2 : 0x00FA);
        CHECK_EQ_INT((int)DSW(ro + 0x44u), be8 ? 0x0019 : 0x000F);
        CHECK_EQ_INT((int)DSB(r + 0x4Bu), (int)(2u - sd));
        CHECK_EQ_INT((int)DSD(ro + 0x24u), 0);
        CHECK_EQ_INT((int)DSD(ro + 0x20u), 0);
        CHECK_EQ_INT((int)DSD(r + 0x1Cu), be8 ? 0x0300 + 0xC80 : 0x0300);
        CHECK_EQ_INT((int)DSD(ro + 0x1Cu), (int)DSD(r + 0x1Cu) - 64);
        CHECK_EQ_INT((int)DSD(ro + 0x18u), (int)DSD(r + 0x18u) + (sw ? -48 : 48));
    }
}

/* 0x21C84 / 0x21D10 (slot, rec, side): only the record's side matters. */
static void check_p52_21_setup(void)
{
    u32 sd, d10;
    for (d10 = 0; d10 < 2u; d10++) {
        for (sd = 0; sd < 2u; sd++) {
            u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
            u32 r = FIGHT_RECS + sd * 0x100u, ro = FIGHT_RECS + (1u - sd) * 0x100u;
            u32 ch = sd ? 4u : 6u;
            p52_seed(1u, 1u, 0);
            DSB(s + 0x7Au) = (u8)ch;
            DSB(s + 0x53u) = 0x53u; DSB(s + 0x52u) = 0x52u; DSB(s + 0x54u) = 0x54u;
            DSD(s + 0x0Cu) = 0x0C0C0C0Cu; DSD(s + 0x18u) = 0x18181818u; DSD(s + 0x1Cu) = 0x1C1C1C1Cu;
            DSB(s + 0x57u) = 0x99u; DSB(s + 0x41u) = 0x01u;
            DSB(o + 0x57u) = 0x98u;
            DSB(DS_0010476E + sd) = 0x77u;
            DSB(DS_0010476E + (1u - sd)) = 0x78u;
            DSW(DS_00104764 + sd * 2u) = 0x1A8Au;
            DSW(DS_00104764 + (1u - sd) * 2u) = 0x2B8Bu;
            if (d10) fighter_21d10(0xDEADu, r, 9u); else fighter_21c84(0xDEADu, r, 9u);
            if (d10) sc_stream(r, fs_stream(7u, ch), 0x40000000u, (u16)(0x1560u + ch));
            else sc_stream(r, fs_stream(1u, ch), 0x40000000u, (u16)(0x1590u + ch));
            CHECK_EQ_INT((int)DSB(DS_0010476E + sd), d10 ? 0 : 1);
            CHECK_EQ_INT((int)DSB(DS_0010476E + (1u - sd)), 0x78);
            CHECK_EQ_INT((int)DSB(s + 0x53u), 7);
            CHECK_EQ_INT((int)DSB(s + 0x52u), 9);
            CHECK_EQ_INT((int)DSB(s + 0x54u), d10 ? 0 : 2);
            CHECK_EQ_INT((int)DSD(s + 0x0Cu), 0x216EC);
            CHECK_EQ_INT((int)DSD(s + 0x18u), d10 ? 0x21B74 : 0x21A88);
            CHECK_EQ_INT((int)DSD(s + 0x1Cu), d10 ? 0x21BE8 : 0x21B08);
            CHECK_EQ_INT((int)DSB(s + 0x57u), 4);
            CHECK_EQ_INT((int)DSB(s + 0x41u), d10 ? 0x81 : 0x01);
            CHECK_EQ_INT((int)DSB(o + 0x57u), 0x98);
            CHECK_EQ_INT((int)DSW(DS_00104764 + sd * 2u), 0);
            CHECK_EQ_INT((int)DSW(DS_00104764 + (1u - sd) * 2u), 0x2B8B);
            CHECK_EQ_INT((int)DSD(ro + 0x08u), 0x00ABCDEF);
        }
    }
}

/* ---- record §54-A: the animation-opcode targets 0x3FF90/0x3FEA8/0x40034/
 * 0x3FC08/0x3FCB0/0x3F77C/0x40434 and 0x21694. Every part runs between
 * g2_save and g2_restore, every row re-seeded by p52_seed. ----------------- */

#define P54_ST    (FIGHT_RECS + 0x21000u)   /* a crafted stream (the dispatch rows) */
#define P54_X     (FIGHT_RECS + 0x200u)     /* a scratch record: +0x51 names a side */
#define P54_A     (FIGHT_RECS + 0x300u)     /* a scratch 0x108080 actor */
#define P54_C7734 0x000C7734u
#define P54_BB2CC 0x000BB2CCu

/* The raw sites: each target's command word and the dword after it (the LE
 * image, fixups applied). */
static const struct { u32 site; u16 cmd; u32 fn; } p54_site[] = {
    { 0x000E7F32u, 0xD000u, 0x3FF90u }, { 0x000D4C6Au, 0xD000u, 0x3FF90u },
    { 0x000E7F9Eu, 0xD000u, 0x3FEA8u }, { 0x000D4CD6u, 0xD000u, 0x3FEA8u },
    { 0x000E8022u, 0xD500u, 0x40034u }, { 0x000D4D5Au, 0xD500u, 0x40034u },
    { 0x000E7D9Au, 0xD100u, 0x3FC08u }, { 0x000E7DDAu, 0xD100u, 0x3FCB0u },
    { 0x000E7DF2u, 0xD500u, 0x3F77Cu }, { 0x000D4FFCu, 0xD000u, 0x40434u },
};

static void check_p54_registered(void)
{
    u32 i;
    for (i = 0; i < sizeof p54_site / sizeof p54_site[0]; i++) {
        CHECK_EQ_INT((int)DSW(p54_site[i].site), (int)p54_site[i].cmd);
        CHECK_EQ_INT((int)DSD(p54_site[i].site + 2u), (int)p54_site[i].fn);
        CHECK(fn_resolve(p54_site[i].fn) != NULL, "a record §54-A stream target is registered");
    }
    /* 0x21694 has no reference and stays unregistered */
    CHECK(fn_resolve(0x21694u) == NULL, "0x21694 is not registered");
    /* the stream 0x40434 sits in, char 5's 0xC92B0 entry */
    CHECK_EQ_INT((int)DSD(0x000C92C4u), 0x000D4FF8);
    /* 0x3FC08's descriptors are type 0x10, whose teardown is 0x3FC90 */
    CHECK_EQ_INT((int)DSB(0x000C76F8u + 4u), 0x10);
    CHECK_EQ_INT((int)DSB(0x000C770Cu + 4u), 0x10);
    CHECK_EQ_INT((int)DSD(DS_000BB9E0 + 0x10u * 0xCu), 0x0003FC90);
    /* 0x40434's mover descriptor: the +0x2C word it starts at */
    CHECK_EQ_INT((int)DSW(P54_BB2CC + 0x0Cu), 0x1000);
}

/* The scratch record for side sd (pset 0x30, a stream sentinel). */
static void p54_x(u32 sd)
{
    mem_fill(P54_X, 0, 0x100u);
    DSB(P54_X + 0x51u) = (u8)sd;
    DSW(P54_X + 0x56u) = 0x30u;
    DSD(P54_X + 0x08u) = 0x0ABCDEF0u;
    DSW(P54_X + 0x34u) = 0x3434u;
    DSW(P54_X + 0x36u) = 0x3636u;
    DSW(P54_X + 0x44u) = 0x4444u;
}

/* 0x3FF90 (rec): the side's slot +0x54 = 2; the record takes +0x36 = 0x300,
 * +0x34 = the slot's +0x4E and +0x44 = 0xC7734[the other slot's char]. */
static void check_p54_3ff90(void)
{
    u32 sd;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u;
        u32 ch = sd ? 5u : 0u, och = sd ? 3u : 6u;
        p52_seed(1u, 3u, 0);
        p54_x(sd);
        DSB(s + 0x7Au) = (u8)ch; DSB(o + 0x7Au) = (u8)och;
        DSW(P54_C7734 + och * 2u) = (u16)(0x4400u + och);
        DSW(P54_C7734 + ch * 2u) = (u16)(0x5500u + ch);
        DSW(s + 0x4Eu) = (u16)(0xBE00u + sd); DSW(o + 0x4Eu) = (u16)(0xCE00u + sd);
        DSB(s + 0x54u) = 0x54u; DSB(o + 0x54u) = 0x45u;
        fighter_3ff90(P54_X);
        CHECK_EQ_INT((int)DSB(s + 0x54u), 2);
        CHECK_EQ_INT((int)DSB(o + 0x54u), 0x45);
        CHECK_EQ_INT((int)DSW(P54_X + 0x34u), (int)(0xBE00u + sd));
        CHECK_EQ_INT((int)DSW(P54_X + 0x36u), 0x0300);
        CHECK_EQ_INT((int)DSW(P54_X + 0x44u), (int)(0x4400u + och));
        CHECK_EQ_INT((int)DSW(r + 0x34u), 0x3434);     /* the writes go to EAX's record */
        CHECK_EQ_INT((int)DSW(r + 0x36u), 0x3636);
        CHECK_EQ_INT((int)DSW(r + 0x44u), 0x4444);
    }
    /* the chain: 0x3FFDC's +0x4E (-(900 / 30), unflipped), then 0x3FF90 */
    p52_seed(5u, 5u, 0);
    fs_flip(0u, 0);
    DSD(FIGHT_RECS + 0x18u) = 0x10000u + 900u;
    DSD(FIGHT_RECS + 0x118u) = 0x10000u;
    DSW(DS_001077B0 + 0x4Eu) = 0x4E4Eu;
    fighter_3ffdc(DS_001077B0, FIGHT_RECS, 0u);
    CHECK_EQ_INT((int)DSD(FIGHT_RECS + 0x08u), 0x000D4C66);
    fighter_3ff90(FIGHT_RECS);
    CHECK_EQ_INT((int)DSW(FIGHT_RECS + 0x34u), 0xFFE2);
}

/* 0x3FEA8 (rec): the +0x57 == 0 gate on the side's slot, then 2/0/4/4, the
 * slot's record's +0x61 = 0 and 0x36870 on it (whole-state reference). Row
 * k = 2 is mode 0x25, where 0x36870 runs 0x385B0 on its argument itself, so
 * 0x36870 must get ctx[4], not the scratch record. */
static void check_p54_3fea8(void)
{
    static const u8 v57[] = { 0u, 1u, 2u, 0x80u };
    u32 sd, i, k;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u, r = FIGHT_RECS + sd * 0x100u;
        for (i = 0; i < sizeof v57; i++) {
            for (k = 0; k < 3u; k++) {
                p52_seed(1u, 3u, 0);
                p54_x(sd);
                DSW(DS_00104B00) = k == 2u ? 0x25u : 0x15u;
                DSB(s + 0x57u) = v57[i];
                DSB(s + 0x52u) = 0x52u; DSB(s + 0x53u) = 0x53u; DSB(s + 0x8Au) = 0x8Au;
                DSB(s + 0x54u) = k == 1u ? 3u : 0u;
                DSB(r + 0x61u) = 0x61u;
                DSB(P54_X + 0x61u) = 0x16u;
                sc_snap();
                if (v57[i] == 0u) {
                    DSB(s + 0x57u) = 2u; DSB(s + 0x8Au) = 0u;
                    DSB(s + 0x52u) = 4u; DSB(s + 0x53u) = 4u;
                    DSB(r + 0x61u) = 0u;
                    fighter_36870(r);
                }
                p52_ref_take();
                sc_back();
                fighter_3fea8(P54_X);
                CHECK(p52_same(), "0x3FEA8: the state is the reference's");
                CHECK_EQ_INT((int)DSB(P54_X + 0x61u), 0x16);
                if (v57[i] == 0u) {
                    CHECK_EQ_INT((int)DSB(r + 0x61u), 0);
                    CHECK_EQ_INT((int)DSB(s + 0x8Au), 0);
                    if (k == 1u) {                  /* case 3 keeps them */
                        CHECK_EQ_INT((int)DSB(s + 0x52u), 4);
                        CHECK_EQ_INT((int)DSB(s + 0x53u), 4);
                    }
                } else {
                    CHECK_EQ_INT((int)DSB(s + 0x57u), (int)v57[i]);
                    CHECK_EQ_INT((int)DSB(s + 0x52u), 0x52);
                    CHECK_EQ_INT((int)DSB(s + 0x8Au), 0x8A);
                    CHECK_EQ_INT((int)DSB(r + 0x61u), 0x61);
                }
            }
        }
    }
}

/* 0x40034 (rec): both DS_001077A8 slots gate it; 0x3BD8C on the side's slot
 * (2/4/0, its record's +0x34 = +/-0x100 by the side's flip, +0x36 = 0x300,
 * +0x44 = 0xC7734[the other slot's char]); then the record on 0xE6F34 (char
 * 0) or 0xD3F58 (char 5) at 3.0. */
static void check_p54_40034(void)
{
    static const u8 chs[3] = { 0u, 5u, 3u };
    u32 sd, fl, c, g;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u, ro = FIGHT_RECS + (1u - sd) * 0x100u;
        u32 och = sd ? 2u : 6u;
        for (fl = 0; fl < 2u; fl++) {
            for (c = 0; c < 3u; c++) {
                u32 ch = chs[c];
                p52_seed(1u, 3u, 0);
                p54_x(sd);
                fs_head(0x000E6F34u, 0x1610u);
                fs_head(0x000D3F58u, 0x1611u);
                DSB(s + 0x7Au) = (u8)ch; DSB(o + 0x7Au) = (u8)och;
                DSW(P54_C7734 + och * 2u) = (u16)(0x4400u + och);
                DSW(P54_C7734 + ch * 2u) = (u16)(0x5500u + ch);
                fs_flip(sd, (int)fl);
                fs_flip(1u - sd, !fl);
                DSB(s + 0x52u) = 0x52u; DSB(s + 0x53u) = 0x53u; DSB(s + 0x54u) = 0x54u;
                DSB(o + 0x52u) = 0x25u; DSB(o + 0x53u) = 0x35u; DSB(o + 0x54u) = 0x45u;
                fighter_40034(P54_X);
                CHECK_EQ_INT((int)DSB(s + 0x54u), 2);
                CHECK_EQ_INT((int)DSB(s + 0x52u), 4);
                CHECK_EQ_INT((int)DSB(s + 0x53u), 0);
                CHECK_EQ_INT((int)DSW(r + 0x34u), fl ? 0xFF00 : 0x0100);
                CHECK_EQ_INT((int)DSW(r + 0x36u), 0x0300);
                CHECK_EQ_INT((int)DSW(r + 0x44u), (int)(0x4400u + och));
                CHECK_EQ_INT((int)DSB(o + 0x52u), 0x25);
                CHECK_EQ_INT((int)DSB(o + 0x53u), 0x35);
                CHECK_EQ_INT((int)DSB(o + 0x54u), 0x45);
                CHECK_EQ_INT((int)DSW(ro + 0x34u), 0x3434);
                CHECK_EQ_INT((int)DSW(P54_X + 0x34u), 0x3434);
                if (ch == 0u) sc_stream(P54_X, 0x000E6F34u, 0x40400000u, 0x1610u);
                else if (ch == 5u) sc_stream(P54_X, 0x000D3F58u, 0x40400000u, 0x1611u);
                else CHECK_EQ_INT((int)DSD(P54_X + 0x08u), 0x0ABCDEF0);
                CHECK_EQ_INT((int)DSD(r + 0x08u), 0x00ABCDEF);
            }
        }
        /* the gates: either slot null changes nothing (the low 0x100 bytes
         * too: a missing own-slot gate would write through the null slot) */
        for (g = 0; g < 2u; g++) {
            u8 low[0x100];
            p52_seed(1u, 3u, 0);
            p54_x(sd);
            DSB(s + 0x53u) = 0x53u;
            DSD(DS_001077A8 + (g ? sd : 1u - sd) * 4u) = 0u;
            memcpy(low, mem, sizeof low);
            p52_ref_take();
            fighter_40034(P54_X);
            CHECK(p52_same(), "0x40034: a null slot changes nothing");
            CHECK(memcmp(low, mem, sizeof low) == 0, "0x40034: nothing written through a null slot");
        }
    }
}

/* 0x3FC08 (rec): the side's descriptor (0xC76F8/0xC770C) takes 0x29C08(side,
 * char) at +0x10, its spawn goes to DS_00108080[side] with +0x60 = 1 and
 * +0x14 = the record, and the record's +0x4B = its +0x56. Whole-state
 * reference of the same steps. */
static void check_p54_3fc08(void)
{
    u32 sd;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u;
        u32 desc = sd ? 0x000C770Cu : 0x000C76F8u, odesc = sd ? 0x000C76F8u : 0x000C770Cu;
        u32 ch = sd ? 5u : 2u;
        u32 ix, h, c, n;
        p52_seed(1u, 3u, 0);
        DSB(s + 0x7Au) = (u8)ch;
        ix = sc_row(ch);
        CHECK(ix != 0xFFFFFFFFu, "a resident INDEX entry");
        if (ix == 0xFFFFFFFFu) return;
        h = sd ? res_handle(ix, 0u) : res_handle(ix, 8u);
        DSD(desc + 0x10u) = 0x10101010u;
        DSD(odesc + 0x10u) = 0x20202020u;
        DSD(DS_00108080 + sd * 4u) = 0x80808080u;
        DSD(DS_00108080 + (1u - sd) * 4u) = 0x84848484u;
        DSB(r + 0x4Bu) = 0x4Bu;
        n = tb_active();
        sc_snap();
        DSD(desc + 0x10u) = h;
        c = actor_spawn((const u32 *)(mem + desc), 0u, 0u, 0u,
                        (u32)(u16)(DSW(r + 0x56u) | 0x0400u));
        DSD(DS_00108080 + sd * 4u) = c;
        DSB(c + 0x60u) = 1u;
        DSD(c + 0x14u) = r;
        DSB(r + 0x4Bu) = DSB(c + 0x56u);
        p52_ref_take();
        sc_back();
        fighter_3fc08(r);
        CHECK(p52_same(), "0x3FC08: the state is the reference's");
        CHECK_EQ_INT((int)DSD(desc + 0x10u), (int)h);
        CHECK_EQ_INT((int)DSD(odesc + 0x10u), 0x20202020);
        CHECK_EQ_INT((int)tb_active(), (int)(n + 1u));
        c = DSD(DS_00108080 + sd * 4u);
        CHECK(actor_index(c) != 0xFFFFFFFFu, "0x3FC08 stores its spawn in DS_00108080[side]");
        if (actor_index(c) != 0xFFFFFFFFu) {
            CHECK_EQ_INT((int)DSB(c + 0x48u), 0x10);
            CHECK_EQ_INT((int)DSB(c + 0x60u), 1);
            CHECK_EQ_INT((int)DSD(c + 0x14u), (int)r);
            CHECK_EQ_INT((int)DSB(r + 0x4Bu), (int)DSB(c + 0x56u));
            CHECK_EQ_INT((int)DSB(c + 0x4Au), (int)(DSW(r + 0x56u) & 0x7Fu));
            CHECK(DSD(c + 0x08u) - 0x000E7E86u < 0x100u, "the spawn walks 0xE7E86");
        }
        CHECK_EQ_INT((int)DSD(DS_00108080 + (1u - sd) * 4u), (int)0x84848484u);
    }
}

/* 0x3FCB0 (rec): the byte 0x105B3A (unsigned, above 1 returns), the other
 * DS_001077A8 slot and its +0x52 == 0x10 gate the 0xBB100 spawn; its +0x56
 * goes to the side's DS_00108080 actor's +0x4B, else to the record's. */
static void check_p54_3fcb0(void)
{
    static const struct { u8 b3a, o52; int onull, act, fire; } row[] = {
        { 0u, 0x10u, 0, 0, 1 }, { 1u, 0x10u, 0, 1, 1 }, { 0u, 0x10u, 0, 1, 1 },
        { 2u, 0x10u, 0, 0, 0 }, { 0x80u, 0x10u, 0, 0, 0 }, { 0xFFu, 0x10u, 0, 1, 0 },
        { 0u, 0x0Fu, 0, 0, 0 }, { 0u, 0x90u, 0, 0, 0 }, { 0u, 0x10u, 1, 0, 0 },
    };
    u32 sd, k;
    for (sd = 0; sd < 2u; sd++) {
        u32 o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u;
        for (k = 0; k < sizeof row / sizeof row[0]; k++) {
            u32 n, c = 0u, i, found = 0u;
            p52_seed(1u, 3u, 0);
            mem_fill(P54_A, 0, 0x100u);
            DSB(P54_A + 0x4Bu) = 0xB4u;
            DSB(DS_00105B3A) = row[k].b3a;
            DSB(o + 0x52u) = row[k].o52;
            if (row[k].onull) DSD(DS_001077A8 + (1u - sd) * 4u) = 0u;
            DSD(DS_00108080 + sd * 4u) = row[k].act ? P54_A : 0u;
            DSD(DS_00108080 + (1u - sd) * 4u) = 0u;
            DSB(r + 0x4Bu) = 0x4Bu;
            n = tb_active();
            sc_snap();
            if (row[k].fire) {
                c = actor_spawn((const u32 *)(mem + 0x000BB100u), 0u, 0u, 0u,
                                (u32)(u16)(DSW(r + 0x56u) | 0x0400u));
                DSB(c + 0x60u) = 1u;
                if (row[k].act) DSB(P54_A + 0x4Bu) = DSB(c + 0x56u);
                else DSB(r + 0x4Bu) = DSB(c + 0x56u);
            }
            p52_ref_take();
            sc_back();
            fighter_3fcb0(r);
            CHECK(p52_same(), "0x3FCB0: the state is the reference's");
            CHECK_EQ_INT((int)tb_active(), (int)(n + (row[k].fire ? 1u : 0u)));
            if (!row[k].fire) {
                CHECK_EQ_INT((int)DSB(r + 0x4Bu), 0x4B);
                CHECK_EQ_INT((int)DSB(P54_A + 0x4Bu), 0xB4);
                continue;
            }
            for (i = actor_list_head(); i != 0; i = actor_next(i))
                if (DSB(i + 0x60u) == 1u && DSD(i + 0x08u) - 0x000E878Eu < 0x40u) { c = i; found++; }
            CHECK_EQ_INT((int)found, 1);
            if (found != 1u) continue;
            CHECK_EQ_INT((int)DSB(c + 0x4Au), (int)(DSW(r + 0x56u) & 0x7Fu));
            if (row[k].act) {
                CHECK_EQ_INT((int)DSB(P54_A + 0x4Bu), (int)DSB(c + 0x56u));
                CHECK_EQ_INT((int)DSB(r + 0x4Bu), 0x4B);
            } else {
                CHECK_EQ_INT((int)DSB(r + 0x4Bu), (int)DSB(c + 0x56u));
            }
        }
    }
}

/* 0x3F77C (rec): the record on 0xE7DF8 at 3.0, +0x36/+0x44/+0x34 (flip-
 * negated), the side's slot +0x54 = 2 and +0x57 = 3, and 0x39834(1 - side,
 * the slot's +0x5F): it stores b in DS_00107D28 and counts on DS_00107D2C
 * [side] (its ctx[0] = the other of 1 - side). */
static void check_p54_3f77c(void)
{
    static const u8 b5f[2] = { 0x21u, 0x07u };
    u32 sd, fl, b;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u, o = DS_001077B0 + (1u - sd) * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u;
        for (fl = 0; fl < 2u; fl++) {
            for (b = 0; b < 2u; b++) {
                p52_seed(1u, 3u, 0);
                p54_x(sd);
                fs_head(0x000E7DF8u, 0x1612u);
                fs_flip(sd, (int)fl);
                fs_flip(1u - sd, !fl);
                DSB(s + 0x5Fu) = b5f[b]; DSB(o + 0x5Fu) = 0x33u;
                DSB(s + 0x54u) = 0x54u; DSB(s + 0x57u) = 0x57u;
                DSW(DS_00107D2C) = 7u; DSW(DS_00107D2C + 2u) = 9u;
                DSD(DS_00107D28) = 0x5A5A5A5Au;
                DSB(DS_00104B14) = 1u;
                fighter_3f77c(P54_X);
                sc_stream(P54_X, 0x000E7DF8u, 0x40400000u, 0x1612u);
                CHECK_EQ_INT((int)DSW(P54_X + 0x36u), 0x028A);
                CHECK_EQ_INT((int)DSW(P54_X + 0x44u), 0x0019);
                CHECK_EQ_INT((int)DSW(P54_X + 0x34u), fl ? 0xFF4C : 0x00B4);
                CHECK_EQ_INT((int)DSB(s + 0x54u), 2);
                CHECK_EQ_INT((int)DSB(s + 0x57u), 3);
                CHECK_EQ_INT((int)DSD(DS_00107D28), (int)b5f[b]);
                CHECK_EQ_INT((int)DSW(DS_00107D2C + sd * 2u), sd ? 10 : 8);
                CHECK_EQ_INT((int)DSW(DS_00107D2C + (1u - sd) * 2u), sd ? 7 : 9);
                CHECK_EQ_INT((int)DSD(r + 0x08u), 0x00ABCDEF);
            }
        }
    }
}

/* 0x40434 (rec): the mover beside the record, its step word, bit 13 and the
 * 0xD501E stream. Rows: side, flip, the other record's x relative to the
 * mover (q = d / 0xE0 = 5, 0x80, 1 and the zero divisor), the unsigned
 * numerator (the descriptor's +0x2C word patched to 0x4000). */
static void check_p54_40434(void)
{
    static const struct { s32 dx; u16 w2c; int step; } row[] = {
        { 5 * 0xE0 + 3, 0x1000u, 0x0800 },     /* q = 5 */
        { -0x7000, 0x1000u, 0x0050 },          /* q = 0x80, the `neg` arm */
        { 0xE0, 0x1000u, 0x2800 },             /* q = 1 */
        { -0xDF, 0x1000u, -1 },                /* q = 0: the PORT: guard */
        { -(5 * 0xE0), 0x4000u, 0x3199 },      /* 0xFFFFF800 / 5, unsigned */
    };
    u32 sd, fl, k;
    for (sd = 0; sd < 2u; sd++) {
        u32 s = DS_001077B0 + sd * 0x94u;
        u32 r = FIGHT_RECS + sd * 0x100u, ro = FIGHT_RECS + (1u - sd) * 0x100u;
        for (fl = 0; fl < 2u; fl++) {
            for (k = 0; k < sizeof row / sizeof row[0]; k++) {
                u32 mx = fl ? 0x11000u : 0xF000u;
                u32 n, c, q, d;
                p52_seed(1u, 3u, 0);
                fs_head(0x000D501Eu, 0x1613u);
                DSW(P54_BB2CC + 0x0Cu) = row[k].w2c;
                DSD(r + 0x14u) = s;
                DSD(r + 0x18u) = 0x10000u;
                DSD(r + 0x1Cu) = 0x500u;
                DSD(r + 0x30u) = 0x00070000u;
                DSW(r + 0x28u) = fl ? 0x4000u : 0u;
                DSD(ro + 0x18u) = mx + (u32)row[k].dx;
                DSD(P52_108098) = 0x98989898u;
                DSW(P52_1080B2) = 0x1234u;
                DSB(DS_00104AE9) = 0x41u;
                n = tb_active();
                sc_snap();
                c = actor_spawn((const u32 *)(mem + P54_BB2CC), mx, 7u, 0x1800u,
                                fl ? 0x4000u : 0u);
                DSW(c + 0x34u) = fl ? 0x00E0u : 0xFF20u;
                DSD(c + 0x14u) = s;
                DSD(P52_108098) = c;
                if (sd) actor_pset_palette(c, 0x0Cu, 0u);
                d = (u32)(row[k].dx < 0 ? -row[k].dx : row[k].dx);
                q = d / 0xE0u;
                if (q != 0u) DSW(P52_1080B2) = (u16)((0x3800u - (u32)DSW(c + 0x2Cu)) / q);
                DSB(DS_00104AE9) = (u8)(DSB(DS_00104AE9) | 0x20u);
                actors_anim_begin(c, 0x000D501Eu, 0x3F800000u);
                p52_ref_take();
                sc_back();
                fighter_40434(r);
                CHECK(p52_same(), "0x40434: the state is the reference's");
                CHECK_EQ_INT((int)tb_active(), (int)(n + 1u));
                c = DSD(P52_108098);
                CHECK(actor_index(c) != 0xFFFFFFFFu, "0x40434 stores its mover at 0x108098");
                if (actor_index(c) == 0xFFFFFFFFu) continue;
                CHECK_EQ_INT((int)DSD(c + 0x18u), (int)mx);
                CHECK_EQ_INT((int)DSD(c + 0x1Cu), 0x1800);
                CHECK_EQ_INT((int)DSW(c + 0x32u), 7);
                CHECK_EQ_INT((int)(DSW(c + 0x28u) & 0x4000u), fl ? 0x4000 : 0);
                CHECK_EQ_INT((int)DSW(c + 0x34u), fl ? 0x00E0 : 0xFF20);
                CHECK_EQ_INT((int)DSD(c + 0x14u), (int)s);
                CHECK_EQ_INT((int)DSW(c + 0x2Cu), (int)row[k].w2c);
                CHECK_EQ_INT((int)(DSW(actor_pset(c) + 2u) & 0x7FFu), sd ? 0x0C : 0x08);
                CHECK_EQ_INT((int)DSW(P52_1080B2), row[k].step < 0 ? 0x1234 : row[k].step);
                CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x61);
                sc_stream(c, 0x000D501Eu, 0x3F800000u, 0x1613u);
            }
        }
        /* no slot at +0x14: nothing */
        p52_seed(1u, 3u, 0);
        DSD(r + 0x14u) = 0u;
        DSB(DS_00104AE9) = 0x41u;
        p52_ref_take();
        fighter_40434(r);
        CHECK(p52_same(), "0x40434: no slot, no mover");
        /* no other slot: the mover, but no step, no bit 13 and no stream */
        p52_seed(1u, 3u, 0);
        DSD(r + 0x14u) = s;
        DSD(r + 0x18u) = 0x10000u;
        DSD(DS_001077A8 + (1u - sd) * 4u) = 0u;
        DSD(P52_108098) = 0x98989898u;
        DSW(P52_1080B2) = 0x1234u;
        DSB(DS_00104AE9) = 0x41u;
        fighter_40434(r);
        CHECK(actor_index(DSD(P52_108098)) != 0xFFFFFFFFu, "the mover spawns before the gate");
        CHECK_EQ_INT((int)DSW(P52_1080B2), 0x1234);
        CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x41);
        CHECK(DSD(DSD(P52_108098) + 0x08u) - 0x000D4EC0u < 0x40u, "the mover keeps its spawn stream");
    }
}

/* The pool made live: 0x40434's mover, stepped by 0x40554 (its bit 13), fires
 * the pool init on the fifth step (0x1000 + 5 * 0x800 = 0x3800), which sets
 * bit 14 (0x407EC's) and clears bit 13. */
static void check_p54_pool_chain(void)
{
    u32 s = DS_001077B0, r = FIGHT_RECS, ro = FIGHT_RECS + 0x100u;
    u32 i, mv, src;
    p52_pool_seed(0u);
    effects_init();
    DSD(DS_001014F0) = 0u;
    src = DSD(DS_001014EC) + (u32)DSW(ro + 0x56u) * 0x20u;
    DSD(src + 0x18u) = P52_AUX;
    DSD(P52_AUX + 0x0Cu) = 0u;
    DSD(r + 0x14u) = s;
    DSD(r + 0x18u) = 0x10000u;
    DSW(r + 0x28u) = 0x4000u;
    DSD(ro + 0x18u) = 0x11000u + 5u * 0xE0u;
    DSW(P52_1080B0) = 0x1234u;
    DSB(DS_00104AE9) = 0x01u;
    fighter_40434(r);
    CHECK_EQ_INT((int)DSW(P52_1080B2), 0x0800);
    CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x21);
    mv = DSD(P52_108098);
    for (i = 0; i < 4u; i++) fighter_40554();
    CHECK_EQ_INT((int)DSW(mv + 0x2Cu), 0x3000);
    CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x21);
    CHECK_EQ_INT((int)DSW(P52_1080B0), 0x1234);
    fighter_40554();
    CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x41);
    CHECK_EQ_INT((int)DSW(P52_1080B0), 8);
    CHECK_EQ_INT((int)(DSB(mv + 0x28u) & 8u), 8);
    CHECK_EQ_INT((int)p52_list(DS_00107EF0, NULL), 8);
}

/* The dispatch: each raw site's bytes (command word, dword, and 0xD100's
 * operand word) copied into a crafted stream ended by a frame word, walked by
 * 0x2BC30, reach the target (opcodes 0x10/0x11/0x15 through fn_resolve). */
static void p54_walk(u32 rec, u32 site)
{
    u32 len = DSW(site) == 0xD100u ? 8u : 6u;
    memcpy(mem + P54_ST, mem + site, len);
    DSW(P54_ST + len) = 0x1620u;
    actors_anim_begin(rec, P54_ST, 0x40400000u);
}

static void check_p54_dispatch(void)
{
    u32 s0 = DS_001077B0, s1 = DS_001077B0 + 0x94u;
    u32 r0 = FIGHT_RECS;
    u32 n;
    /* 0xD000 0x3FF90 */
    p52_seed(1u, 3u, 0);
    p54_x(0u);
    DSW(s0 + 0x4Eu) = 0x4E4Eu;
    p54_walk(P54_X, 0x000E7F32u);
    CHECK_EQ_INT((int)DSW(P54_X + 0x34u), 0x4E4E);
    CHECK_EQ_INT((int)DSW(P54_X + 0x36u), 0x0300);
    /* 0xD000 0x3FEA8 */
    p52_seed(1u, 3u, 0);
    p54_x(0u);
    DSW(DS_00104B00) = 0x15u;
    DSB(s0 + 0x57u) = 0u; DSB(s0 + 0x54u) = 3u;
    DSB(r0 + 0x61u) = 0x61u;
    p54_walk(P54_X, 0x000D4CD6u);
    CHECK_EQ_INT((int)DSB(r0 + 0x61u), 0);
    CHECK_EQ_INT((int)DSB(s0 + 0x52u), 4);
    /* 0xD500 0x40034 */
    p52_seed(1u, 3u, 0);
    p54_x(0u);
    DSB(s0 + 0x53u) = 0x53u;
    p54_walk(P54_X, 0x000E8022u);
    CHECK_EQ_INT((int)DSB(s0 + 0x53u), 0);
    CHECK_EQ_INT((int)DSW(r0 + 0x36u), 0x0300);
    /* 0xD100 0x3FC08 */
    p52_seed(1u, 3u, 0);
    DSD(DS_00108080) = 0x80808080u;
    DSD(DS_000A8A98 + (u32)DSB(s0 + 0x7Au) * 4u) = P54_A;    /* a null handle row */
    mem_fill(P54_A, 0, 0x10u);
    n = tb_active();
    p54_walk(r0, 0x000E7D9Au);
    CHECK_EQ_INT((int)tb_active(), (int)(n + 1u));
    CHECK(actor_index(DSD(DS_00108080)) != 0xFFFFFFFFu, "0xD100 reaches 0x3FC08");
    /* 0xD100 0x3FCB0 */
    p52_seed(1u, 3u, 0);
    DSB(DS_00105B3A) = 0u;
    DSB(s1 + 0x52u) = 0x10u;
    DSD(DS_00108080) = 0u;
    DSB(r0 + 0x4Bu) = 0x4Bu;
    n = tb_active();
    p54_walk(r0, 0x000E7DDAu);
    CHECK_EQ_INT((int)tb_active(), (int)(n + 1u));
    CHECK(DSB(r0 + 0x4Bu) != 0x4Bu, "0xD100 reaches 0x3FCB0");
    /* 0xD500 0x3F77C */
    p52_seed(1u, 3u, 0);
    p54_x(0u);
    DSB(s0 + 0x5Fu) = 0x21u;
    DSD(DS_00107D28) = 0x5A5A5A5Au;
    DSB(DS_00104B14) = 1u;
    p54_walk(P54_X, 0x000E7DF2u);
    CHECK_EQ_INT((int)DSD(DS_00107D28), 0x21);
    CHECK_EQ_INT((int)DSB(s0 + 0x57u), 3);
    /* 0xD000 0x40434 */
    p52_seed(1u, 3u, 0);
    DSD(r0 + 0x14u) = s0;
    DSD(P52_108098) = 0x98989898u;
    DSB(DS_00104AE9) = 0x01u;
    DSD(FIGHT_RECS + 0x118u) = 0x20000u;
    p54_walk(r0, 0x000D4FFCu);
    CHECK(actor_index(DSD(P52_108098)) != 0xFFFFFFFFu, "0xD000 reaches 0x40434");
    CHECK_EQ_INT((int)DSB(DS_00104AE9), 0x21);
}

/* 0x21694 (side), as check_fs_3e8e4. */
static void check_p54_21694(void)
{
    u32 sd;
    for (sd = 0; sd < 2u; sd++) {
        u32 r = FIGHT_RECS + sd * 0x100u, ro = FIGHT_RECS + (1u - sd) * 0x100u;
        p52_seed(1u, 3u, 0);
        DSB(r + 0x4Bu) = 0x4Bu;
        DSB(ro + 0x4Bu) = 0xB4u;
        DSD(ro + 0x24u) = 0x24242424u;
        DSD(r + 0x24u) = 0x42424242u;
        fighter_21694(sd);
        CHECK_EQ_INT((int)DSB(r + 0x4Bu), 0);
        CHECK_EQ_INT((int)DSD(ro + 0x24u), 0x40000000);
        CHECK_EQ_INT((int)DSB(ro + 0x4Bu), 0xB4);
        CHECK_EQ_INT((int)DSD(r + 0x24u), 0x42424242);
    }
}

int test_pose_pool(void)
{
    int before = g_failures;
    check_p52_registered();
    check_p54_registered();
    g2_save(); check_p54_3ff90(); g2_restore();
    g2_save(); check_p54_3fea8(); g2_restore();
    g2_save(); check_p54_40034(); g2_restore();
    g2_save(); check_p54_3fc08(); g2_restore();
    g2_save(); check_p54_3fcb0(); g2_restore();
    g2_save(); check_p54_3f77c(); g2_restore();
    g2_save(); check_p54_40434(); g2_restore();
    g2_save(); check_p54_pool_chain(); g2_restore();
    g2_save(); check_p54_dispatch(); g2_restore();
    g2_save(); check_p54_21694(); g2_restore();
    g2_save(); check_p52_3f7f4(); g2_restore();
    g2_save(); check_p52_3fd30(); g2_restore();
    g2_save(); check_p52_3f85c(); g2_restore();
    g2_save(); check_p52_3fef8(); g2_restore();
    g2_save(); check_p52_3ffdc(); g2_restore();
    g2_save(); check_p52_40608(); g2_restore();
    g2_save(); check_p52_407ec_count(); g2_restore();
    g2_save(); check_p52_407ec_walk(); g2_restore();
    g2_save(); check_p52_40554(); g2_restore();
    g2_save(); check_p52_215b0(); g2_restore();
    g2_save(); check_p52_21_hooks(); g2_restore();
    g2_save(); check_p52_21_cb(); g2_restore();
    g2_save(); check_p52_21_setup(); g2_restore();
    return g_failures - before;
}

/* ---- record k7-k12 §6..§10: the fight-area K12 voice sites ----------------
 * One table per batch (k12_b2_fight here; Tasks 7-10 add k12_c_fight,
 * k12_d1, k12_d2 and k12_d3), each with its own #define K12_<B>_ROWS and one
 * size check and one tf_voice_sites call in test_fight_voice_sites. The rules
 * are record k7-k12 §4.2's: a row is one wiring point, its ids the wired
 * voices on the driver's path in raw order; a driver seeds every scratch
 * byte it reads; no bump-heap growth; a later batch adds its own drivers and
 * table and never edits an earlier batch's rows. */

/* Addresses symbols.h has no name for. */
#define VF_POOL      0x03F70000u   /* the §51-A private pool (test_game.c's RA_POOL) */
#define VF_PSET      0x03FA0000u   /* its pset block (RA_PSET) */
#define VF_00108396  0x00108396u   /* byte: 0x48F98's once bit 7 */
#define VF_00108397  0x00108397u   /* byte: 0x48F98's node count */
#define VF_00104529  0x00104529u   /* byte: the sprite-flag config byte */
#define VF_NODE      (FIGHT_RECS + 0x3000u)  /* a type-0x2D list node */
#define VF_REC       (FIGHT_RECS + 0x3100u)  /* its actor record */
#define VF_THEM      (FIGHT_RECS + 0x3200u)  /* the slot record it measures against */

/* A private actor pool (test_game.c's vs_pools), so no driver spawns into
 * the image's own pool. */
static void vf_pools(void)
{
    DSD(DS_001014F4) = VF_POOL;
    DSD(DS_001014EC) = VF_PSET;
    actors_reset();
}

/* Row 4: 0x48F98 (update entry 1, fn_register(0x48F98)) with one node on
 * the in-use list DS_00108368 at phase 1 (0x48FB7), 0x2000 away from slot
 * DS_001078FD = 0's record (> 0x1000, 0x4909C) and the count
 * DS_00108397 = 1, so n = 0 is not above 0 (0x490D8). */
static void vf_2d_far(void)
{
    void (*f)(void) = fn_resolve(0x48F98u);
    vf_pools();
    mem_fill(VF_NODE, 0, 0x300u);
    DSD(DS_00108368) = VF_NODE;
    DSD(VF_NODE) = DS_00108368;
    DSB(VF_NODE + 0x0Cu) = 1u;
    DSD(VF_NODE + 8u) = VF_REC;
    DSD(VF_REC + 0x18u) = 0x2000u;
    DSB(DS_001078FD) = 0u;
    DSD(DS_001077B0) = VF_THEM;
    DSB(VF_00108396) = 0u;
    DSB(VF_00108397) = 1u;
    if (f != NULL) f();
}
/* Row 5: 0x3D784 (type 0x09's teardown, fn_register(0x3D784)): a tail jmp. */
static void vf_3d784(void)
{
    void (*f)(u32) = (void (*)(u32))fn_resolve(0x3D784u);
    mem_fill(VF_REC, 0, 0x80u);
    if (f != NULL) f(VF_REC);
}
/* Rows 18/30 and 19/28: 0x4367C with DS_00104B1D != 3 (0x43738) or = 3
 * (0x4454C then 0x444C8); DS_00104B1F = 0 spawns no side, DS_00108173 = 0
 * takes the 0xC887F / 0xC8880 arms. */
static void vf_hook_4367c_b1d(u8 b1d)
{
    vf_pools();
    DSB(DS_00104B1F) = 0u;
    DSB(DS_00108173) = 0u;
    DSB(DS_00104B1D) = b1d;
    fight_hook_4367c();
}
static void vf_hook_4367c(void)   { vf_hook_4367c_b1d(0u); }
static void vf_hook_4367c_3(void) { vf_hook_4367c_b1d(3u); }
/* Rows 24..26: 0x430E8, check_mode_1a_hooks' (k2) arm: DS_00104B17 = 2
 * (0x25848 keeps the stage, no draw), DS_00104B1F = 3 (no 0x41350),
 * characters 0 and 6. */
static void vf_hook_430e8(void)
{
    vf_pools();
    DSB(DS_00104B17) = 2u;
    DSB(DS_00104B1D) = 0u;
    DSB(DS_00104B1F) = 3u;
    DSB(DS_0010816A) = 0u;
    DSB(DS_0010816B) = 6u;
    DSB(DS_00108173) = 1u;
    fight_hook_430e8();
}
/* Row 31: 0x4142C, unconditional. */
static void vf_hook_4142c(void)
{
    vf_pools();
    fight_hook_4142c();
}
/* Rows 64/65: 0x3531C side 0 with a live slot (DS_001077A8[0] = slot 0,
 * its record non-zero, 0x3539A), the voice tick DS_001078F6 = 1 so the
 * decrement reaches 0 (0x353B9 `jg`), DS_00104529 bit 1 clear (no 0x2B150)
 * and +0x53 = 4 (0x3540E: +0x56 only). */
static void vf_3531c(void)
{
    mem_fill(VF_REC, 0, 0x80u);
    DSD(DS_001077A8) = DS_001077B0;
    DSD(DS_001077B0) = VF_REC;
    DSW(DS_001078F6) = 1u;
    DSB(VF_00104529) = 0u;
    DSB(DS_001077B0 + 0x53u) = 4u;
    fighter_state_3531c(0u);
}

/* Record k7-k12 §6, batch B2 (fight.c, actors.c, fighter.c): pure-state
 * voices, all case 1 or 5. */
#define K12_B2_FIGHT_ROWS 12
static const TfVoiceSite k12_b2_fight[] = {
    {   4u, vf_2d_far,       1u, { 0xF1u } },                  /* 0x490E1 */
    {   5u, vf_3d784,        1u, { 0x4Fu } },                  /* 0x3D789 */
    {  18u, vf_hook_4367c,   3u, { 0x100u, 0x2Eu, 0x30u } },   /* 0x43741 */
    {  19u, vf_hook_4367c_3, 3u, { 0x100u, 0x2Eu, 0x30u } },   /* 0x444D1 */
    {  24u, vf_hook_430e8,   3u, { 0x31u, 0x2Du, 0x2Fu } },    /* 0x430F2 */
    {  25u, vf_hook_430e8,   3u, { 0x31u, 0x2Du, 0x2Fu } },    /* 0x4328A */
    {  26u, vf_hook_430e8,   3u, { 0x31u, 0x2Du, 0x2Fu } },    /* 0x43294 */
    {  28u, vf_hook_4367c_3, 3u, { 0x100u, 0x2Eu, 0x30u } },   /* 0x44626 */
    {  30u, vf_hook_4367c,   3u, { 0x100u, 0x2Eu, 0x30u } },   /* 0x43729 */
    {  31u, vf_hook_4142c,   1u, { 0x32u } },                  /* 0x41483 */
    {  64u, vf_3531c,        2u, { 0xECu, 0xE0u } },           /* 0x353C0 */
    {  65u, vf_3531c,        2u, { 0xECu, 0xE0u } },           /* 0x353CA */
};

/* ---- record k7-k12 §7, batch C: the oracle-path sample voices ------------
 * Every id below is a table read from the raw bytes (record §1.1 row 0.2):
 * 0xBDFFA, 0xBDAA8, 0xE9308, 0xE933C, 0xBE008, 0xE9358, indexed by a byte
 * of the 0x3AFC4 triple (0xDE114 + c*11, c = char << 6 | reaction) or by
 * the slot's char +0x7A; record §7.1 gives each row's index. */
#define VC_S0    DS_001077B0
#define VC_S1    (DS_001077B0 + 0x94u)
#define VC_R0    FIGHT_RECS
#define VC_R1    (FIGHT_RECS + 0x100u)
#define VC_R2    (FIGHT_RECS + 0x200u)         /* row 58's thrown record */
#define VC_ST    (FIGHT_RECS + 0x3A00u)        /* tg_seed's seven stream words */
#define VC_E1    (FIGHT_RECS + 0x3300u)        /* row 38's two list entries */
#define VC_E2    (FIGHT_RECS + 0x3340u)
#define VC_ER1   (FIGHT_RECS + 0x3400u)        /* and their actor records */
#define VC_ER2   (FIGHT_RECS + 0x3480u)
#define VC_SHADE (FIGHT_RECS + 0x3500u)        /* a non-zero +0x10 (no 0x2AE14) */

/* Row 1: 0x2B2A0 opcode 0x2E through actors_anim_begin's pre-walk (every
 * command whose high byte has bit 7). `9F2E` is the 0x1F prefix (0x2B2B1
 * `and ah,0x1f`) with op byte 0x2E and mode 0, so the operand is the next
 * word (0x2B932); two commands carry the ids 0xD3 and 0xCD, then the word
 * 0 (bit 7 clear) ends the walk. */
static void vc_anim_2e(void)
{
    static const u16 s[5] = { 0x9F2Eu, 0x00D3u, 0x9F2Eu, 0x00CDu, 0x0000u };
    u32 rec, i;
    vf_pools();
    rec = tf_anim_alloc_record();
    for (i = 0; i < 5u; i++) DSW(ANIM_SCRATCH + i * 2u) = s[i];
    if (rec != 0u) actors_anim_begin(rec, ANIM_SCRATCH, 0x40400000u);
}

/* Rows 33..35: 0x4A634 through fight_effects_pass (0x4A591, unconditional)
 * with an empty entry list (tf_demo_fixture), mode 3 (not 7/8/9, so no
 * mode-9 block and no DS_001088BF tail draw). Both slots' +0x42 bit 1 set
 * (0x4A640); the side's DS_001088A8 byte picks the arm (0x4A655..0x4A697). */
static void vc_crowd(u8 r0, u8 r1, u32 seed)
{
    (void)tf_demo_fixture();
    DSW(DS_00104B00) = 3u;
    DSB(VC_S0 + 0x42u) = 2u;
    DSB(VC_S1 + 0x42u) = 2u;
    DSB(DS_001088A8) = r0;
    DSB(DS_001088A8 + 1u) = r1;
    rng_seed(seed);
    fight_effects_pass();
}
/* Row 33: 0x20 and 0x3F (both ends of 0x20..0x3F), then a second pass with
 * side 0 at 0x2A only. Seed 18 draws rng_next(3) = 0, 1, 2: 0xCD, 0xCE, 0xCF
 * (0x4A669..0x4A688). */
static void vc_crowd_cd(void)
{
    vc_crowd(0x20u, 0x3Fu, 18u);
    DSB(VC_S0 + 0x42u) = 2u;
    DSB(DS_001088A8) = 0x2Au;
    fight_effects_pass();
}
/* Rows 34/35: 0x10 and 0x17 (both ends of 0x10..0x17). Seed 12 draws
 * rng_next(2) = 1, 1 (side 0: 0xC9 then 0xDA) and 1, 0 (side 1: 0xCA then
 * 0xDB). */
static void vc_crowd_c9(void) { vc_crowd(0x10u, 0x17u, 12u); }

/* Row 38: 0x4B470 through fight_effects_pass case 8 (0x4A08A): two entries
 * with +0x1C bit 6 (0x4A097; bit 7 clear, so 0x4B69C returns at 0x4B6B3),
 * the holder side 0 not in its hold (0x4AF04: slot 0's char 0, its record's
 * +8 = 0 outside 0xE7B02..0xE7B50), a +0x4A link (0x4A0B7) and a shadow in
 * +0x10 (0x4B4BB). The voice is 0xD1 when rec+0x48 - 0x20 < 3 (signed,
 * 0x4B483..0x4B489), else 0xD0: 0x20 gives 0xD1, 0x23 gives 0xD0.
 * DS_00104B1D = 3 ends 0x4B470 at 0x4B547, before the eighth-hit tail. */
static void vc_trample(void)
{
    vf_pools();
    (void)tf_demo_fixture();
    mem_fill(VC_E1, 0, 0x300u);
    DSW(DS_00104B00) = 3u;
    DSB(DS_00104B1D) = 3u;
    DSB(VC_S0 + 0x7Au) = 0u;
    DSD(DS_0010884C) = VC_E1;
    DSD(VC_E1) = VC_E2;
    DSD(VC_E2) = DS_0010884C;
    DSD(VC_E1 + 8u) = VC_ER1;
    DSD(VC_E2 + 8u) = VC_ER2;
    DSB(VC_ER1 + 0x48u) = 0x20u;
    DSB(VC_ER2 + 0x48u) = 0x23u;
    DSB(VC_ER1 + 0x4Au) = 1u;
    DSB(VC_ER2 + 0x4Au) = 2u;
    DSD(VC_E1 + 0x10u) = VC_SHADE;
    DSD(VC_E2 + 0x10u) = VC_SHADE;
    DSB(VC_E1 + 0x1Cu) = 0x40u;
    DSB(VC_E2 + 0x1Cu) = 0x40u;
    DSB(VC_E1 + 0x1Eu) = 8u;
    DSB(VC_E2 + 0x1Eu) = 8u;
    fight_effects_pass();
}

/* Row 58: 0x3B938 on slot 0, char 4, its +0x08 record at +0x48 = 2 (not
 * 4, 0x3B948): 0xBDFFA[4] = 0xAC (0x3B9A1..0x3B9B8). */
static void vc_3b938(void)
{
    (void)tf_hit_fixture(4u);
    mem_fill(VC_R2, 0, 0x68u);
    DSB(VC_R2 + 0x48u) = 2u;
    DSD(VC_S0 + 0x08u) = VC_R2;
    fighter_3b938(VC_S0);
}
/* Row 60: 0x36710's third arm (the flag +0x58 = 2, rec+0x36 = 0 and
 * rec+0x1C = 0, 0x367B5..0x367BC): 0x6E. */
static void vc_36710(void)
{
    (void)tf_hit_fixture(0u);
    fight_reset_slot_pair(VC_S0, VC_S1, VC_R0, VC_R1);
    DSB(VC_R0 + 0x51u) = 0u;
    DSB(VC_S0 + 0x58u) = 2u;
    DSW(VC_R0 + 0x36u) = 0u;
    DSD(VC_R0 + 0x1Cu) = 0u;
    fighter_state_36710(VC_S0, VC_R0);
}
/* Row 61: 0x35E6C, after the +0x41 store (0x35ED0): 0x6D. */
static void vc_35e6c(void)
{
    (void)tf_hit_fixture(0u);
    fight_reset_slot_pair(VC_S0, VC_S1, VC_R0, VC_R1);
    DSB(VC_R0 + 0x51u) = 0u;
    DSW(DS_001088E0) = 0u;
    DSB(VC_S0 + 0x7Au) = 0u;
    DSB(VC_R0 + 0x56u) = 0u;
    fighter_state_35e6c(VC_S0, VC_R0);
}
/* Row 66: 0x35E04 on side 1's record with its owner slot in +0x14
 * (0x35E0B), char 2: 0xBDAA8[2] = 0x7B (0x35E26..0x35E38). 0x3BC70 reads
 * the side's DS_00107D40 row. */
static void vc_35e04(void)
{
    u32 row = FIGHT_RECS + 0x3830u;
    (void)tf_hit_fixture(0u);
    fight_reset_slot_pair(VC_S0, VC_S1, VC_R0, VC_R1);
    DSW(row) = 23u;
    DSW(row + 2u) = 550u;
    DSW(row + 4u) = 150u;
    DSD(DS_00107D40 + 4u) = row;
    DSB(VC_R1 + 0x51u) = 1u;
    DSD(VC_R1 + 0x14u) = VC_S1;
    DSB(VC_S1 + 0x7Au) = 2u;
    fighter_35e04(VC_R1);
}
/* Row 67: 0x34E2C, char 0, reaction 0: the triple's stream 0xE6F94 is
 * non-zero (0x34F85) and its callback 0; byte[0xDE114 + 7] = 12, so
 * 0xE9308[12] = 0x8E (0x34F8B..0x34FA4). */
static void vc_react_stream(void)
{
    (void)tf_hit_fixture(0u);
    fight_reset_slot_pair(VC_S0, VC_S1, VC_R0, VC_R1);
    hit_reaction_apply(0u, 0u);
}
/* Row 68: char 0, reaction 0x2A: no stream, the callback 0x3E3A8 (0x35017);
 * byte[0xDE114 + 0x2A*11 + 7] = 10, so 0xE9308[10] = 0x87 (0x35019..0x35032). */
static void vc_react_cb(void)
{
    (void)tf_hit_fixture(0u);
    fight_reset_slot_pair(VC_S0, VC_S1, VC_R0, VC_R1);
    hit_reaction_apply(0u, 0x2Au);
}
/* Row 69: 0x3D17C with the slot's +0x08 clear (0x3D187): 0x91. */
static void vc_3d17c(void)
{
    (void)tf_hit_fixture(0u);
    fight_reset_slot_pair(VC_S0, VC_S1, VC_R0, VC_R1);
    fighter_3d17c(VC_S0, VC_R0, 0u);
}
/* Row 70: 0x1461C with ctx[2]'s +0x57 = 2 (0x146D7) runs 0x146F0 to its
 * last call: 0xB1 (0x14807). check_char3_*'s D3 seed. */
static void vc_1461c(void)
{
    c3_seed(VC_S0, VC_S1, VC_R0, VC_R1, VC_ST);
    DSB(VC_S0 + 0x57u) = 2u;
    DSB(VC_S0 + 0x42u) = 0x0Cu;
    DSB(VC_S1 + 0x42u) = 0x08u;
    DSW(DS_001088E0) = 0u;
    DSB(DS_000FD11C) = 0u;
    fighter_1461c(VC_S0, VC_R0, 0u);
}
/* Row 71: 0x14814, the voice right after 0x339AC (0x14824/0x14829): 0xB0. */
static void vc_14814(void)
{
    c3_seed(VC_S0, VC_S1, VC_R0, VC_R1, VC_ST);
    fighter_14814(VC_S0, VC_R0, 0u);
}
/* Rows 72/76: 0x14D7C(0) runs 0x39834(1, slot 0's +0x5F) at 0x14DF5, then
 * 0xB3 (0x14E38). 0x39834 swaps to ctx[0] = 0, so the triple is slot 0's
 * char: char 4, reaction 0x25 gives byte[0xDE114 + 0x125*11 + 8] = 8, and
 * 0xE933C[8] = 0x46, the case-3 id (0x39959..0x3996E). The throw's other
 * seeds are check_throw_3c208's (I). */
static void vc_14d7c(void)
{
    c3_seed(VC_S0, VC_S1, VC_R0, VC_R1, VC_ST);
    DSB(VC_S0 + 0x42u) = 0u;
    DSB(VC_S1 + 0x42u) = 0u;
    DSB(VC_S1 + 0x7Au) = 4u;
    DSB(VC_S0 + 0x7Au) = 4u;
    DSB(VC_S0 + 0x5Fu) = 0x25u;
    DSD(VC_R0 + 0x18u) = (u32)(-8000 - 192);
    DSD(VC_S0 + 0x2Cu) = (u32)-8000;
    DSD(VC_R1 + 0x18u) = 6000u - 64u;
    DSD(VC_S1 + 0x2Cu) = 8000u;
    DSW(DS_00107D2C) = 3u;
    fighter_14d7c(0u);
}
/* Row 75: 0x39CC8 phase 3 (0x39CE2) landing: slot 1's +0x30 = 5632, equal
 * to word[0xBD884 + 3*2] (0x39E13 setge), then the 0xBB1DC dust spawn
 * (0x39ED0, into the private pool) and 0x6C (0x39EDA). */
static void vc_39cc8(void)
{
    vf_pools();
    kb_seed(VC_S0, VC_S1, VC_R0, VC_R1);
    DSB(VC_S1 + 0x58u) = 3u;
    DSD(VC_S1 + 0x30u) = 5632u;
    DSB(VC_R1 + 0x28u) = 0u;
    fighter_39cc8(VC_S1, 1u);
}
/* Row 92: 0x3AAFC on slot 0 (side 0), reaction 0: 0x39834(0, 0) swaps to
 * ctx[0] = 1, slot 1's char 0: byte[0xDE114 + 8] = 2, 0xE933C[2] = 0x65
 * (0x3AB7C); then slot 1's +0x5F = 0x20 passes 0x3A280 (0x3AB8D) and slot
 * 0's char 3 gives 0xBE008[3] = 0x9F (0x3AB96..0x3ABAF). check_pose_entry's
 * setup, slot 0's +0x5F = 0xFF (no second triple). */
static void vc_reaction_apply(void)
{
    pose_chain_setup(VC_S0, VC_S1, VC_R0, VC_R1);
    DSB(VC_S0 + 0x5Fu) = 0xFFu;
    DSB(VC_S1 + 0x5Fu) = 0x20u;
    DSB(VC_S0 + 0x53u) = 0u;
    DSB(VC_S0 + 0x41u) = 0u;
    DSB(VC_S0 + 0x7Au) = 3u;
    fighter_reaction_apply(VC_S0, 0u);
}
/* Row 93: 0x3AD98(0, the 0x3AFC4 triple of side 0 at char 4, reaction
 * 0x24): byte[anim[0] + 9] = 5 (0x3ADAA..0x3ADB4), 0xE9358[5] = 0x74; its
 * anim[2] word 0 spawns no stream (0x3AE1E). */
static void vc_3ad98(void)
{
    u32 anim[3];
    pose_chain_setup(VC_S0, VC_S1, VC_R0, VC_R1);
    DSB(VC_S0 + 0x7Au) = 4u;
    fighter_anim_triple(anim, 0u, 0x24);
    fighter_3ad98(0u, anim);
}
/* Row 94: 0x15350 on slot 1 with the other side's 0x468D8 false (slot 0's
 * +0x52 = 0, +0x10 = 0; 0x15360..0x15375): 0xAF (0x153BF). */
static void vc_15350(void)
{
    c3_seed(VC_S0, VC_S1, VC_R0, VC_R1, VC_ST);
    fighter_15350(VC_S1, VC_R1, 0u);
}

